import React, { useState, useCallback, useEffect } from "react";

// localStorage管理
const LS_USED = "fe_used_ids";
const LS_SESSIONS = "fe_sessions";
const LS_MISSED = "fe_missed";
const LS_LIFETIME = "fe_lifetime"; // 生涯累計(セッション履歴とは別に、間引かれず増え続ける集計)
const LS_CYCLE = "fe_cycle"; // 今回の周回成績(問題プールを1周する間、リロードしても消えない)
const LS_QVERSION = "fe_qversion"; // 問題内容のバージョン識別子(内容が変わったら周回・復習リストを自動リセットするために使う)

const store = {
  saveIds(ids){ try{ localStorage.setItem(LS_USED, JSON.stringify(ids)); }catch(e){} },
  loadIds(){ try{ const v=localStorage.getItem(LS_USED); return v?JSON.parse(v):[]; }catch(e){ return []; } },
  addSession(session){
    try{
      // 生涯累計を先に確定(この時点ではまだ今回のsessionを含まない状態で
      // 初回マイグレーションのベースラインを作る。二重計上を防ぐため必ず
      // sessionsの更新より前に行う)
      const lt = this.loadLifetime();
      lt.totalAnswered += session.total;
      lt.totalCorrect += session.correct;
      Object.entries(session.cats||{}).forEach(([c,v])=>{
        if(!lt.byCat[c]) lt.byCat[c] = {ok:0,total:0};
        lt.byCat[c].ok += v.ok;
        lt.byCat[c].total += v.total;
      });
      this.saveLifetime(lt);

      const sessions = this.loadSessions();
      sessions.push(session);
      // 直近セッション一覧の表示用に最新100件だけ保持(この間引きは表示用のみで、
      // 累計成績はfe_lifetimeに別途加算保存するため間引きの影響を受けない)
      if(sessions.length > 100) sessions.splice(0, sessions.length - 100);
      localStorage.setItem(LS_SESSIONS, JSON.stringify(sessions));
    }catch(e){}
  },
  loadSessions(){ try{ const v=localStorage.getItem(LS_SESSIONS); return v?JSON.parse(v):[]; }catch(e){ return []; } },
  saveLifetime(lt){ try{ localStorage.setItem(LS_LIFETIME, JSON.stringify(lt)); }catch(e){} },
  loadLifetime(){
    try{
      const v = localStorage.getItem(LS_LIFETIME);
      if(v) return JSON.parse(v);
    }catch(e){}
    // 初回: fe_lifetimeが存在しない場合、既存のfe_sessions(直近最大100件、
    // =この呼び出し時点でまだ今回のsessionは含まれていない)の合計値を初期値として
    // 引き継ぐ。これより前に間引かれてしまった分は復元不可能だが、
    // 以後は間引かれずに正しく積み上がっていく。
    const sessions = this.loadSessions();
    const lt = { totalAnswered:0, totalCorrect:0, byCat:{} };
    sessions.forEach(sess=>{
      lt.totalAnswered += sess.total;
      lt.totalCorrect += sess.correct;
      Object.entries(sess.cats||{}).forEach(([c,v])=>{
        if(!lt.byCat[c]) lt.byCat[c] = {ok:0,total:0};
        lt.byCat[c].ok += v.ok;
        lt.byCat[c].total += v.total;
      });
    });
    return lt;
  },
  saveMissed(list){ try{ localStorage.setItem(LS_MISSED, JSON.stringify(list)); }catch(e){} },
  loadMissed(){ try{ const v=localStorage.getItem(LS_MISSED); return v?JSON.parse(v):[]; }catch(e){ return []; } },
  // 今回の周回成績: 問題プールを1周する(usedIdsがリセットされる)まで保持し、
  // ページのリロードやタブの再読込では消えないようにする
  saveCycle(data){ try{ localStorage.setItem(LS_CYCLE, JSON.stringify(data)); }catch(e){} },
  loadCycle(){ try{ const v=localStorage.getItem(LS_CYCLE); return v?JSON.parse(v):{history:[],catStats:{}}; }catch(e){ return {history:[],catStats:{}}; } },
  clearCycle(){ try{ localStorage.removeItem(LS_CYCLE); }catch(e){} },
};

const CATS = [
  "すべて","基礎理論","コンピュータシステム","ネットワーク","情報セキュリティ",
  "データベース","アルゴリズム・プログラミング","ソフトウェア・HI",
  "システム開発","プロジェクトマネジメント","サービスマネジメント・監査","経営・戦略・法務",
];

const ALL_QUESTIONS = [{"id":1,"cat":"プロジェクトマネジメント","topic":"クリティカルパスの判定(複数経路)","q":"図の作業経路Pは3+5+2日、経路Qは4+3+2日である。クリティカルパスはどれか。","choices":[{"label":"ア","text":"経路P"},{"label":"イ","text":"両方"},{"label":"ウ","text":"経路Q"},{"label":"エ","text":"判断できない"}],"correct":"ア","hint":"Pは3+5+2=10日、Qは4+3+2=9日。全体工期を決めるのは最長経路であるPがクリティカルパスとなる。","image":"/images/diagrams/diagram2-q16.png"},{"id":2,"cat":"経営・戦略・法務","topic":"PPM(プロダクトポートフォリオマネジメント)の象限","q":"図のPPMで、市場成長率が高く相対的市場占有率も高い領域Xの名称はどれか。","choices":[{"label":"ア","text":"負け犬"},{"label":"イ","text":"問題児"},{"label":"ウ","text":"金のなる木"},{"label":"エ","text":"花形"}],"correct":"エ","hint":"成長率・占有率とも高い領域は「花形」。成長率が低く占有率が高い領域が「金のなる木」である。","image":"/images/diagrams/diagram-q19.png"},{"id":3,"cat":"プロジェクトマネジメント","topic":"アローダイアグラムの最短所要日数","q":"図の作業A~Eについて、プロジェクト全体の最短所要日数はどれか。矢印横の数値は日数である。","choices":[{"label":"ア","text":"10日"},{"label":"イ","text":"8日"},{"label":"ウ","text":"9日"},{"label":"エ","text":"11日"}],"correct":"ア","hint":"経路はA-C-E=3+4+3=10日、B-D-E=2+5+3=10日。合流点は両経路の完了を待つ必要があるため、全体は10日となる。","image":"/images/diagrams/diagram-q18.png"},{"id":4,"cat":"基礎理論","topic":"2の補数表現による負の数の表し方","q":"8ビットの2の補数表現で、10進数の-5を表すビット列はどれか。","choices":[{"label":"ア","text":"10000101"},{"label":"イ","text":"00000101"},{"label":"ウ","text":"11111010"},{"label":"エ","text":"11111011"}],"correct":"エ","hint":"5(00000101)の全ビットを反転すると11111010、それに1を加えると11111011となり、これが-5の2の補数表現である。"},{"id":5,"cat":"ネットワーク","topic":"HTTPリクエストとレスポンスの識別","q":"図の通信で、ブラウザがWebサーバへHTMLを要求するメッセージはどれか。","choices":[{"label":"ア","text":"HTTPレスポンス"},{"label":"イ","text":"DNS応答"},{"label":"ウ","text":"ARP応答"},{"label":"エ","text":"HTTPリクエスト"}],"correct":"エ","hint":"ブラウザからサーバへ送る要求がHTTPリクエスト。サーバから返るHTMLや状態コードがHTTPレスポンスである。","image":"/images/diagrams/diagram2-q10.png"},{"id":6,"cat":"基礎理論","topic":"集合演算(差集合)","q":"図のベン図で色が付いた「Aには含まれるがBには含まれない」領域を表す式はどれか。","choices":[{"label":"ア","text":"A∩B"},{"label":"イ","text":"A∪B"},{"label":"ウ","text":"B−A"},{"label":"エ","text":"A−B"}],"correct":"エ","hint":"Aのうち、Bとの共通部分を除いた領域を表す式はA−B。差集合は引く順序によって結果が変わる点に注意。","image":"/images/diagrams/diagram2-q3.png"},{"id":7,"cat":"ネットワーク","topic":"TCP3ウェイハンドシェイクのACK番号","q":"図のTCP通信で、最初のSYNのシーケンス番号が100、相手のSYNが500のとき、「?」のACK番号はどれか。","choices":[{"label":"ア","text":"100"},{"label":"イ","text":"101"},{"label":"ウ","text":"500"},{"label":"エ","text":"501"}],"correct":"エ","hint":"SYNはシーケンス番号を1つ消費する。サーバから届いたSeq=500のSYNに対する確認応答なので、ACK=501となる。","image":"/images/diagrams/diagram-q9.png"},{"id":8,"cat":"ネットワーク","topic":"DMZの役割","q":"図のネットワーク構成で、外部公開Webサーバを置くのに最も適切な領域はどれか。","choices":[{"label":"ア","text":"管理者PC内"},{"label":"イ","text":"インターネット"},{"label":"ウ","text":"社内LAN"},{"label":"エ","text":"DMZ"}],"correct":"エ","hint":"外部公開サーバはインターネットと社内LANの間のDMZに置き、侵害時に社内へ直接到達しにくくする。","image":"/images/diagrams/diagram2-q19.png"},{"id":9,"cat":"アルゴリズム・プログラミング","topic":"再帰呼び出しとスタック使用量の関係","q":"再帰の深さがnに達する再帰関数を実行した場合、一般的にスタック上に積まれる呼び出し情報(スタックフレーム)の量として適切な説明はどれか。","choices":[{"label":"ア","text":"再帰の深さに関わらず消費メモリは一定である"},{"label":"イ","text":"スタックフレームは1つしか使われない"},{"label":"ウ","text":"再帰呼び出しはヒープ領域のみを使用しスタックは使わない"},{"label":"エ","text":"再帰の深さに比例してスタックフレームが積み重なり、消費メモリもnに比例して増加する"}],"correct":"エ","hint":"各再帰呼び出しごとにローカル変数や戻り先の情報を保持するスタックフレームが積まれるため、深い再帰は多くのメモリを消費する。"},{"id":10,"cat":"サービスマネジメント・監査","topic":"是正処置と予防処置の違い","q":"「既に発生した不具合の原因を除去し再発を防ぐ活動」と、「将来発生しうる潜在的な不具合を未然に防ぐ活動」の組合せとして適切なものはどれか。","choices":[{"label":"ア","text":"予防処置 — 是正処置(順序が逆)"},{"label":"イ","text":"是正処置と予防処置に違いはない"},{"label":"ウ","text":"是正処置は将来のリスクのみを対象とする"},{"label":"エ","text":"是正処置 — 予防処置"}],"correct":"エ","hint":"是正処置は既に顕在化した問題への事後対応、予防処置はまだ発生していない潜在的リスクへの事前対応という違いがある。"},{"id":11,"cat":"コンピュータシステム","topic":"デュアルチャネルメモリの効果","q":"主記憶(メモリモジュール)を2枚1組で並列に動作させることで、単体使用時と比べてメモリの理論上の転送帯域幅を向上させる技術はどれか。","choices":[{"label":"ア","text":"仮想記憶"},{"label":"イ","text":"キャッシュメモリ(CPUとメモリの間の高速な記憶装置)"},{"label":"ウ","text":"デュアルチャネル方式"},{"label":"エ","text":"ライトバック方式"}],"correct":"ウ","hint":"複数のメモリモジュールを並列にアクセスすることで、単一チャネルに比べてデータ転送帯域を広げられる。"},{"id":12,"cat":"システム開発","topic":"コードカバレッジの意味","q":"テストがソースコードのうちどれだけの割合を実行したかを数値で示す指標を何と呼ぶか。","choices":[{"label":"ア","text":"スループット(単位時間あたりの処理量を示す別指標)"},{"label":"イ","text":"コードカバレッジ(網羅率)"},{"label":"ウ","text":"バグ密度(コード量あたりの不具合件数を示す別指標)"},{"label":"エ","text":"リードタイム(工程の所要時間を示す別指標)"}],"correct":"イ","hint":"カバレッジが高いからといって不具合がないことを保証するわけではないが、テストの網羅性を測る目安として広く使われる。"},{"id":13,"cat":"コンピュータシステム","topic":"並列・直列システムの稼働率計算","q":"図のシステムは装置A(稼働率0.9)とB(0.8)の並列部分に、装置C(0.95)が直列接続されている。全体の稼働率はどれか。独立故障とする。","choices":[{"label":"ア","text":"0.684"},{"label":"イ","text":"0.931"},{"label":"ウ","text":"0.760"},{"label":"エ","text":"0.950"}],"correct":"イ","hint":"AとBの並列稼働率は1-(1-0.9)(1-0.8)=0.98。それに直列のCを掛け、0.98×0.95=0.931。","image":"/images/diagrams/diagram-q20.png"},{"id":14,"cat":"ネットワーク","topic":"VLAN間通信の制約","q":"図で同じスイッチに接続されていても、VLAN10の端末とVLAN20の端末が直接通信できない主な理由はどれか。","choices":[{"label":"ア","text":"IPアドレスが必ず重複するから"},{"label":"イ","text":"異なるブロードキャストドメインだから"},{"label":"ウ","text":"MACアドレスが存在しないから"},{"label":"エ","text":"TCPが使えないから"}],"correct":"イ","hint":"VLANごとに論理的なLANが分離される。異なるVLAN間の通信にはルータまたはL3スイッチによるルーティングが必要になる。","image":"/images/diagrams/diagram2-q11.png"},{"id":15,"cat":"コンピュータシステム","topic":"クロック周波数からのMIPS値計算(新数値)","q":"クロック周波数800MHzのCPUで、平均CPI(1命令あたりの平均クロックサイクル数)が4のとき、このCPUの性能を表すMIPS値(1秒間に実行できる命令数を百万単位で表した値)はどれか。","choices":[{"label":"ア","text":"800MIPS"},{"label":"イ","text":"200MIPS"},{"label":"ウ","text":"0.005MIPS"},{"label":"エ","text":"3200MIPS"}],"correct":"イ","hint":"MIPS=クロック周波数÷CPI÷10^6=800×10^6÷4÷10^6=200MIPSとして求められる。"},{"id":16,"cat":"コンピュータシステム","topic":"配列要素のアドレス計算","q":"整数型配列aの先頭アドレスが1000、1要素が4バイトのとき、a[6]の先頭アドレスはどれか。添字は0から始まる。","choices":[{"label":"ア","text":"1020"},{"label":"イ","text":"1006"},{"label":"ウ","text":"1024"},{"label":"エ","text":"1028"}],"correct":"ウ","hint":"a[0]が1000なので、a[6]は6要素分進んだ位置。1000+6×4=1024。","image":"/images/diagrams/diagram-q3.png"},{"id":17,"cat":"経営・戦略・法務","topic":"コアコンピタンスの概念","q":"他社には容易に模倣できない、企業の中核となる独自の強み・技術力を何と呼ぶか。","choices":[{"label":"ア","text":"M&A"},{"label":"イ","text":"ベンチマーキング(他社比較による改善手法)"},{"label":"ウ","text":"アウトソーシング(外部委託そのものを指す別概念)"},{"label":"エ","text":"コアコンピタンス"}],"correct":"エ","hint":"コアコンピタンスを軸に経営資源を集中投入することで、持続的な競争優位を築く戦略の基礎となる。"},{"id":18,"cat":"コンピュータシステム","topic":"マルチスレッドにおけるコンテキストスイッチのコスト","q":"OSが複数のスレッドを切り替えて実行する(コンテキストスイッチ)際に発生するオーバーヘッドの説明として適切なものはどれか。","choices":[{"label":"ア","text":"スレッドを切り替えるとメモリ使用量が自動的に減る"},{"label":"イ","text":"切替えのたびに処理速度が必ず向上する"},{"label":"ウ","text":"実行中のレジスタの内容等を退避・復元する処理が必要となり、頻繁な切替えは全体の処理効率を低下させうる"},{"label":"エ","text":"コンテキストスイッチには一切のコストがかからない"}],"correct":"ウ","hint":"頻繁すぎるコンテキストスイッチは、本来の処理よりも切替え自体のオーバーヘッドが目立つようになり、スループットを低下させることがある。"},{"id":19,"cat":"ネットワーク","topic":"DHCPによるIPアドレスのリース更新","q":"DHCPサーバから割り当てられたIPアドレスには有効期限(リース期間)があり、クライアントはリース期間の一定割合が経過した時点で更新要求を送る。この仕組みの目的はどれか。","choices":[{"label":"ア","text":"IPアドレスを永久に固定するため"},{"label":"イ","text":"通信速度を向上させるため"},{"label":"ウ","text":"使われなくなったIPアドレスを回収し、限られたアドレス空間を有効に再利用するため"},{"label":"エ","text":"MACアドレスを定期的に変更するため"}],"correct":"ウ","hint":"ネットワークから離脱した端末のアドレスをいつまでも保持し続けないよう、リース期限切れで自動的に回収される。"},{"id":20,"cat":"システム開発","topic":"ペアプログラミングの利点","q":"2人の開発者が1台のコンピュータで、1人がコードを書き、もう1人がリアルタイムでレビューしながら共同で開発を進める手法の利点はどれか。","choices":[{"label":"ア","text":"1人で開発するより必ず開発速度が2倍になる"},{"label":"イ","text":"2人分の給与コストを削減できる"},{"label":"ウ","text":"コードの品質向上や知識共有をリアルタイムに行え、バグの早期発見につながりやすい"},{"label":"エ","text":"レビュー工程を完全に省略できる"}],"correct":"ウ","hint":"常時レビューが行われる状態になるため、コードレビューを別工程として設ける場合より早期に問題を発見しやすい。"},{"id":21,"cat":"コンピュータシステム","topic":"仮想記憶におけるページングの仕組み","q":"実際の主記憶容量を超えるメモリ空間をプログラムに提供するため、ディスク上の補助記憶と主記憶の間でデータを一定サイズの単位でやり取りする仕組みはどれか。","choices":[{"label":"ア","text":"ページング(仮想記憶)"},{"label":"イ","text":"キャッシング(主記憶とCPUの間の高速化の仕組み)"},{"label":"ウ","text":"デフラグメンテーション"},{"label":"エ","text":"ミラーリング"}],"correct":"ア","hint":"実際には存在しない大きなメモリ空間があるかのようにプログラムに見せかけ、必要な部分だけを主記憶に読み込む。"},{"id":22,"cat":"データベース","topic":"ER図の多重度(カーディナリティ)","q":"図の関係で、「一人の顧客は複数の注文を行えるが、一つの注文は必ず一人の顧客に属する」を表す多重度はどれか。","choices":[{"label":"ア","text":"顧客多:注文1"},{"label":"イ","text":"顧客1:注文1"},{"label":"ウ","text":"顧客多:注文多"},{"label":"エ","text":"顧客1:注文多"}],"correct":"エ","hint":"顧客を基準に見ると注文は複数作れるが、注文から顧客へは一人に決まるため、顧客1対注文多の関係になる。","image":"/images/diagrams/diagram-q10.png"},{"id":23,"cat":"サービスマネジメント・監査","topic":"インシデントの優先度付け(緊急度×影響度)","q":"発生したインシデントへの対応順序を決める際、一般的に用いられる優先度の判断基準の組合せはどれか。","choices":[{"label":"ア","text":"インシデントの発生時刻のみ"},{"label":"イ","text":"対応にかかる予想コストのみ"},{"label":"ウ","text":"発見した担当者の役職のみ"},{"label":"エ","text":"緊急度と影響度の組合せ"}],"correct":"エ","hint":"影響範囲が広く、かつ緊急性が高いインシデントほど優先的に対応すべきという考え方に基づき優先度が決定される。"},{"id":24,"cat":"情報セキュリティ","topic":"ゼロデイ攻撃の定義","q":"ソフトウェアの脆弱性が発見されてから、開発者による修正プログラム(パッチ)が提供されるまでの間に、その脆弱性を悪用して行われる攻撃を何と呼ぶか。","choices":[{"label":"ア","text":"ゼロデイ攻撃"},{"label":"イ","text":"DoS攻撃(サービス妨害を目的とした攻撃)"},{"label":"ウ","text":"フィッシング(偽サイト等を使った情報詐取)"},{"label":"エ","text":"ソーシャルエンジニアリング(人の心理的な隙を突く攻撃手法)"}],"correct":"ア","hint":"パッチが存在しない(修正までの猶予がゼロである)期間に行われる攻撃であることから、この名前が付けられている。"},{"id":25,"cat":"アルゴリズム・プログラミング","topic":"流れ図のトレース(累積和)","q":"図の流れ図にn=5を入力したとき、最後に表示されるsの値はどれか(s←0, i←1として、i≦nの間s←s+i, i←i+1を繰り返す)。","choices":[{"label":"ア","text":"15"},{"label":"イ","text":"5"},{"label":"ウ","text":"10"},{"label":"エ","text":"25"}],"correct":"ア","hint":"1+2+3+4+5=15。判定→処理→更新の順で追うと、i=6になった時点でループを抜けsが15で確定する。","image":"/images/diagrams/diagram-q14.png"},{"id":26,"cat":"基礎理論","topic":"アルゴリズムの正当性の検証における帰納的な考え方","q":"ループを含むアルゴリズムが正しく動作することを検証する際に用いられる「ループ不変条件」の考え方の説明として適切なものはどれか。","choices":[{"label":"ア","text":"ループが何回実行されるかを事前に数えるだけの手法である"},{"label":"イ","text":"ループ内の変数の値を全て記録しておく手法である"},{"label":"ウ","text":"ループの実行前・各繰返しの前後で常に成り立つ条件を定め、それによってループ終了時に期待する結果が得られることを示す"},{"label":"エ","text":"ループの実行速度を測定するための手法である"}],"correct":"ウ","hint":"帰納法的に「初期状態で成り立つ」「1回の繰返しで条件が保たれる」の2点を示すことで、ループ終了時の正しさを論理的に保証できる。"},{"id":27,"cat":"コンピュータシステム","topic":"USBとSATAの用途の違い","q":"コンピュータの周辺機器接続に広く使われるUSBと、主に内蔵ストレージ(HDD/SSD)の接続に使われるSATAの一般的な違いの説明として適切なものはどれか。","choices":[{"label":"ア","text":"SATAは外付け機器専用の規格である"},{"label":"イ","text":"USBとSATAは全く同じ用途で完全に互換性がある"},{"label":"ウ","text":"USBはストレージ以外の機器を接続できない"},{"label":"エ","text":"USBはキーボードやマウス等の多様な周辺機器接続に対応する汎用インタフェース、SATAはストレージ機器の高速な内部接続に特化したインタフェース"}],"correct":"エ","hint":"SATAはストレージ装置とのデータ転送に最適化されているのに対し、USBは幅広い種類の周辺機器を対象とした汎用的な規格である。"},{"id":28,"cat":"システム開発","topic":"Factoryパターンの目的","q":"オブジェクトの生成処理を専用のメソッドやクラスに切り出し、呼び出し側が具体的なクラス名を意識せずにインスタンスを取得できるようにするデザインパターンはどれか。","choices":[{"label":"ア","text":"Singletonパターン(唯一のインスタンスを保証するパターン)"},{"label":"イ","text":"Factoryパターン"},{"label":"ウ","text":"Observerパターン(状態変化を通知するパターン)"},{"label":"エ","text":"Adapterパターン(インタフェースの違いを吸収するパターン)"}],"correct":"イ","hint":"生成ロジックを一箇所にまとめることで、生成対象のクラスが変わっても呼び出し側のコードへの影響を抑えられる。"},{"id":29,"cat":"システム開発","topic":"CI/CDパイプラインの目的","q":"コードの変更をリポジトリに反映するたびに、自動的にビルド・テスト・デプロイを実行する一連の仕組みを何と呼ぶか。","choices":[{"label":"ア","text":"バージョン管理システム(変更履歴の管理自体を指す別概念)"},{"label":"イ","text":"CI/CDパイプライン"},{"label":"ウ","text":"デザインパターン"},{"label":"エ","text":"ウォーターフォールモデル(開発プロセス全体のモデルであり、自動化の仕組みそのものではない)"}],"correct":"イ","hint":"手作業によるビルドやデプロイのミスを減らし、変更を頻繁かつ安全にリリースできるようにすることを目的とする。"},{"id":30,"cat":"システム開発","topic":"V字モデルにおけるテスト工程の対応関係","q":"V字モデルの開発プロセスにおいて、「基本設計」の工程と対応関係にあるテスト工程はどれか。","choices":[{"label":"ア","text":"受入テスト(要求分析・企画と対応)"},{"label":"イ","text":"システムテスト(要件定義と対応)"},{"label":"ウ","text":"単体テスト(詳細設計と対応)"},{"label":"エ","text":"結合テスト"}],"correct":"エ","hint":"V字モデルでは、上流工程での設計内容が、対応する下流のテスト工程で検証されるという対応関係が意識される。"},{"id":31,"cat":"基礎理論","topic":"命題論理の真偽判定","q":"命題「PならばQ」(P→Q)が偽になるのは、PとQがそれぞれどのような真偽値のときか。","choices":[{"label":"ア","text":"Pが偽でQが真のとき"},{"label":"イ","text":"PとQが両方とも真のとき"},{"label":"ウ","text":"PとQが両方とも偽のとき"},{"label":"エ","text":"Pが真でQが偽のとき"}],"correct":"エ","hint":"「P→Q」は、前提Pが真であるにもかかわらず結論Qが偽である場合にのみ偽となる。それ以外の組合せでは真になる。"},{"id":32,"cat":"コンピュータシステム","topic":"LRUページ置換方式","q":"主記憶のページ枠が3個で、参照列が 1, 2, 3, 1, 4 のとき、LRU方式で4を読み込む際に追い出されるページはどれか。","choices":[{"label":"ア","text":"1"},{"label":"イ","text":"4"},{"label":"ウ","text":"3"},{"label":"エ","text":"2"}],"correct":"エ","hint":"4を読む直前の枠内は1・2・3。直近の利用は1が最新、次に3、最も長く使われていないのは2であり、2が追い出される。","image":"/images/diagrams/diagram-q6.png"},{"id":33,"cat":"コンピュータシステム","topic":"RISCとCISCの設計思想の違い","q":"命令セットの設計方針として、単純で実行時間が均一な命令を多数組み合わせて処理を実現する方式と、複雑で多機能な命令を少数用意する方式の組合せの名称はどれか。","choices":[{"label":"ア","text":"RISC(縮小命令セットコンピュータ) — CISC(複合命令セットコンピュータ)"},{"label":"イ","text":"両方ともCISCに分類される"},{"label":"ウ","text":"両方ともRISCに分類される"},{"label":"エ","text":"CISC — RISC(順序が逆)"}],"correct":"ア","hint":"RISCは単純な命令をパイプライン処理で高速に実行することを重視し、CISCは1命令で複雑な処理を完結させることを重視する設計思想である。"},{"id":34,"cat":"アルゴリズム・プログラミング","topic":"動的計画法によるコイン問題","q":"1円、5円、10円のコインを使って、最小枚数でちょうどある金額を支払う問題を解く際、部分問題の最適解を表全体に保存しながら解いていく手法はどれか。","choices":[{"label":"ア","text":"貪欲法(常に最大値のコインを選ぶ方式では最適解にならない場合がある)"},{"label":"イ","text":"線形探索"},{"label":"ウ","text":"動的計画法"},{"label":"エ","text":"二分探索"}],"correct":"ウ","hint":"コインの組合せによっては貪欲法(常に大きい額面を優先)が最適解を出せない場合があり、動的計画法により全ての部分問題を考慮することで最適解が保証される。"},{"id":35,"cat":"データベース","topic":"デッドロック回避のためのロック順序統一","q":"複数のトランザクションが複数のテーブルに対してロックを取得する際、デッドロックの発生を予防する基本的な対策として適切なものはどれか。","choices":[{"label":"ア","text":"ロックの取得順序をトランザクションごとに毎回変える"},{"label":"イ","text":"ロックを一切取得せずに更新処理を行う"},{"label":"ウ","text":"全てのトランザクションで、ロックを取得するテーブルの順序をあらかじめ統一しておく"},{"label":"エ","text":"トランザクションを1つも使わずに処理する"}],"correct":"ウ","hint":"取得順序が異なると互いに相手が持つロックの解放を待ち合う循環待ちが発生しうるが、順序を統一すればこの循環を防げる。"},{"id":36,"cat":"基礎理論","topic":"隣接行列から隣接リストへの変換","q":"頂点数4のグラフを隣接行列で表現した場合と隣接リストで表現した場合を比較したとき、辺の数が非常に少ない(疎な)グラフにおいて隣接リストの方がメモリ効率で有利になる理由はどれか。","choices":[{"label":"ア","text":"隣接行列は辺の有無に関わらず頂点数の2乗のメモリを必要とするが、隣接リストは実際に存在する辺の数に応じたメモリで済むため"},{"label":"イ","text":"両者のメモリ使用量に違いはないため"},{"label":"ウ","text":"隣接リストは常に頂点数の2乗のメモリを必要とするため"},{"label":"エ","text":"隣接行列は辺の数に応じたメモリしか使わないため"}],"correct":"ア","hint":"隣接行列はO(頂点数²)のメモリを常に消費するのに対し、隣接リストはO(頂点数+辺数)のメモリで済むため、疎なグラフほど差が大きくなる。"},{"id":37,"cat":"ネットワーク","topic":"ARPの役割","q":"同一ネットワーク内で、宛先のIPアドレスから対応するMACアドレスを問い合わせて解決するプロトコルはどれか。","choices":[{"label":"ア","text":"DNS(ドメイン名からIPアドレスを求めるプロトコル)"},{"label":"イ","text":"ICMP"},{"label":"ウ","text":"RARP(MACアドレスからIPアドレスを求める逆方向のプロトコル)"},{"label":"エ","text":"ARP"}],"correct":"エ","hint":"ARPは同一セグメント内でブロードキャストにより問い合わせを行い、該当ホストからMACアドレスの応答を受け取る。"},{"id":38,"cat":"アルゴリズム・プログラミング","topic":"望ましいハッシュ関数の性質","q":"ハッシュ表における衝突をできるだけ減らすために、ハッシュ関数に求められる望ましい性質はどれか。","choices":[{"label":"ア","text":"異なる入力に対してハッシュ値ができるだけ均一に分散して算出されること"},{"label":"イ","text":"計算に時間がかかるほど良いとされること"},{"label":"ウ","text":"入力値をそのまま出力すること(恒等関数であること)"},{"label":"エ","text":"全ての入力に対して同じハッシュ値を返すこと"}],"correct":"ア","hint":"ハッシュ値が特定の範囲に偏って集中すると、そのバケットでの衝突が増え、探索効率が低下する。"},{"id":39,"cat":"ネットワーク","topic":"NAPT(ポート番号を利用したアドレス変換)","q":"複数の端末が1つのグローバルIPアドレスを共有してインターネットへ接続できるようにするため、送信元ポート番号も併せて変換する技術はどれか。","choices":[{"label":"ア","text":"ARP"},{"label":"イ","text":"NAPT(IPマスカレード)"},{"label":"ウ","text":"単純なNAT(1対1のアドレス変換に限られる)"},{"label":"エ","text":"DHCP"}],"correct":"イ","hint":"ポート番号まで含めて変換・管理することで、1つのグローバルIPアドレスの下に複数端末の通信を同時に多重化できる。"},{"id":40,"cat":"システム開発","topic":"命令網羅の判定","q":"図の制御フローで、すべての処理箱を少なくとも1回実行するテスト基準はどれか。","choices":[{"label":"ア","text":"複数条件網羅"},{"label":"イ","text":"命令網羅"},{"label":"ウ","text":"判定条件網羅"},{"label":"エ","text":"同値分割"}],"correct":"イ","hint":"全ての命令(処理)を最低1回実行するのが命令網羅。分岐の真・偽の両方までは要求しない点が判定条件網羅との違い。","image":"/images/diagrams/diagram2-q15.png"},{"id":41,"cat":"アルゴリズム・プログラミング","topic":"重み付きグラフの最短経路","q":"図の重み付きグラフで、頂点AからDまでの最短距離はどれか。辺の数値は距離である。","choices":[{"label":"ア","text":"7"},{"label":"イ","text":"8"},{"label":"ウ","text":"5"},{"label":"エ","text":"6"}],"correct":"エ","hint":"候補はA-D=9、A-B-D=2+6=8、A-C-D=5+2=7、A-B-C-D=2+2+2=6。最短は6。","image":"/images/diagrams/diagram-q16.png"},{"id":42,"cat":"プロジェクトマネジメント","topic":"三点見積り(PERT)による所要期間の算出","q":"ある作業の楽観値が4日、最頻値が7日、悲観値が16日のとき、PERT法(三点見積り)による期待所要期間はどれか。","choices":[{"label":"ア","text":"7日"},{"label":"イ","text":"10日"},{"label":"ウ","text":"8日"},{"label":"エ","text":"9日"}],"correct":"ウ","hint":"PERT法の期待値は(楽観値+4×最頻値+悲観値)÷6で求める。(4+4×7+16)÷6=48÷6=8日となる。"},{"id":43,"cat":"ネットワーク","topic":"最長一致によるルーティング","q":"ルータが図の表を最長一致で検索する。宛先192.168.1.70のパケットを送るインタフェースはどれか。","choices":[{"label":"ア","text":"eth1"},{"label":"イ","text":"eth2"},{"label":"ウ","text":"eth0"},{"label":"エ","text":"eth3"}],"correct":"ア","hint":"192.168.1.70は/24にも/26(64~127の範囲)にも一致するが、最長一致の原則によりより長いプレフィックス/26のeth1が選ばれる。","image":"/images/diagrams/diagram-q8.png"},{"id":44,"cat":"ネットワーク","topic":"BGPとOSPFの違い(EGP/IGP)","q":"組織内(自律システム内)の経路情報交換に使われるOSPFと、異なる組織間(インターネット全体)の経路情報交換に使われるBGPの分類の組合せはどれか。","choices":[{"label":"ア","text":"両方ともEGPに分類される"},{"label":"イ","text":"両方ともIGPに分類される"},{"label":"ウ","text":"OSPF:EGP、BGP:IGP(組合せが逆)"},{"label":"エ","text":"OSPF:IGP(内部ゲートウェイプロトコル)、BGP:EGP(外部ゲートウェイプロトコル)"}],"correct":"エ","hint":"IGPは自律システム(AS)内、EGPは異なるAS間の経路制御に使われるという役割分担がある。"},{"id":45,"cat":"データベース","topic":"第一正規形(繰返し項目の排除)","q":"1つのセルに複数の値(例えば1人の顧客が複数の電話番号を持つ場合、それらをまとめて1つの列に格納すること)を格納している状態を解消し、1つのセルには1つの値だけを持たせる正規化の段階はどれか。","choices":[{"label":"ア","text":"第三正規形(推移的関数従属の排除)"},{"label":"イ","text":"第一正規形"},{"label":"ウ","text":"ボイス・コッド正規形"},{"label":"エ","text":"第二正規形(部分関数従属の排除)"}],"correct":"イ","hint":"繰返し項目を排除して1セル1値の状態にすることが第一正規形の要件であり、正規化の最初の段階にあたる。"},{"id":46,"cat":"ネットワーク","topic":"光ファイバとメタルケーブルの伝送特性","q":"光ファイバケーブルが、メタル(銅線)ケーブルと比較して長距離・高速な伝送に適しているとされる主な理由はどれか。","choices":[{"label":"ア","text":"電磁的な信号劣化(ノイズの影響)を受けにくく、より長い距離を高速に伝送できるため"},{"label":"イ","text":"電気を一切通さないため通信できない"},{"label":"ウ","text":"価格が常に安いため"},{"label":"エ","text":"設置工事が不要なため"}],"correct":"ア","hint":"光信号は電磁誘導によるノイズの影響を受けにくく、長距離伝送でも信号品質を保ちやすい。"},{"id":47,"cat":"コンピュータシステム","topic":"ラウンドロビンスケジューリング","q":"図はタイムクウォンタム2のラウンドロビンである。時刻0にP1(5)、P2(3)、P3(1)が到着したとき、最初に終了するプロセスはどれか。括弧内は必要CPU時間。","choices":[{"label":"ア","text":"P3"},{"label":"イ","text":"P2"},{"label":"ウ","text":"P1"},{"label":"エ","text":"同時に終了"}],"correct":"ア","hint":"P3は必要時間が1で、最初に割り当てられる区間内で処理が完了するため、最初に終了する。","image":"/images/diagrams/diagram-q5.png"},{"id":48,"cat":"基礎理論","topic":"2進数の加算","q":"図の2進数 101101 と 001111 を加算した結果はどれか。","choices":[{"label":"ア","text":"111100"},{"label":"イ","text":"111000"},{"label":"ウ","text":"110100"},{"label":"エ","text":"1001100"}],"correct":"ア","hint":"右端の桁から順に加算し、桁が2になったら0を書いて左へ1繰り上げる。10進数で45+15=60であり、2進数では111100となる。","image":"/images/diagrams/diagram2-q1.png"},{"id":49,"cat":"コンピュータシステム","topic":"キャッシュメモリの平均アクセス時間","q":"図の階層で、CPUから見た平均アクセス時間として正しい式はどれか。キャッシュのヒット率をhとする。","choices":[{"label":"ア","text":"h×10+(1-h)×110"},{"label":"イ","text":"(10+100)÷h"},{"label":"ウ","text":"h×10+(1-h)×100"},{"label":"エ","text":"10+h×100"}],"correct":"ア","hint":"ヒット時は10ns。ミス時はキャッシュ確認の10nsに主記憶100nsが加わり110ns。よってh×10+(1-h)×110。","image":"/images/diagrams/diagram-q4.png"},{"id":50,"cat":"ネットワーク","topic":"ルータが参照する情報","q":"図のPC-AからPC-Bへ送信するとき、異なるネットワーク間を中継する機器Rが主に参照する情報はどれか。","choices":[{"label":"ア","text":"URL"},{"label":"イ","text":"宛先IPアドレス"},{"label":"ウ","text":"利用者名"},{"label":"エ","text":"宛先ポート番号"}],"correct":"イ","hint":"ルータはネットワーク層で動作し、宛先IPアドレスとルーティング表を参照して転送先を決定する。","image":"/images/diagrams/diagram-q7.png"},{"id":51,"cat":"アルゴリズム・プログラミング","topic":"ハッシュ表の衝突処理方式","q":"図のハッシュ表で、衝突を連結リストで処理する方式の名称はどれか。","choices":[{"label":"ア","text":"チェイン法"},{"label":"イ","text":"基数交換法"},{"label":"ウ","text":"二分探索法"},{"label":"エ","text":"線形探索法"}],"correct":"ア","hint":"同じハッシュ値になった要素を同じバケットの連結リストにつなぐ方式がチェイン法である。","image":"/images/diagrams/diagram2-q5.png"},{"id":52,"cat":"システム開発","topic":"スクラムにおけるプロダクトバックログの役割","q":"プロダクトに必要な機能や改善事項を、優先順位付けした一覧として管理するスクラムの成果物はどれか。","choices":[{"label":"ア","text":"スプリントバックログ(1スプリント分に絞り込んだ作業一覧)"},{"label":"イ","text":"プロダクトバックログ"},{"label":"ウ","text":"リスク登録簿"},{"label":"エ","text":"バーンダウンチャート(進捗の可視化グラフ)"}],"correct":"イ","hint":"プロダクトオーナーが優先順位を管理し、スプリント計画の際にここから作業を選び出してスプリントバックログを作る。"},{"id":53,"cat":"基礎理論","topic":"浮動小数点形式(IEEE 754)","q":"図の形式で、符号部1ビット、指数部8ビット、仮数部23ビットから成る規格はどれか。","choices":[{"label":"ア","text":"IEEE 754 倍精度"},{"label":"イ","text":"IEEE 754 単精度"},{"label":"ウ","text":"BCD"},{"label":"エ","text":"UTF-8"}],"correct":"イ","hint":"1+8+23=合計32ビットはIEEE 754の単精度形式。倍精度は1+11+52ビットの合計64ビットになる。","image":"/images/diagrams/diagram2-q2.png"},{"id":54,"cat":"アルゴリズム・プログラミング","topic":"深さ優先探索(DFS)の特徴","q":"グラフの探索において、1つの経路を行き止まりまで進んでから後戻りして別の経路を試す探索方法はどれか。","choices":[{"label":"ア","text":"深さ優先探索(DFS)"},{"label":"イ","text":"二分探索(整列済み配列を対象とする探索)"},{"label":"ウ","text":"線形探索"},{"label":"エ","text":"幅優先探索(BFS、始点に近い順に探索する)"}],"correct":"ア","hint":"スタック(再帰呼び出しを含む)を用いて実装されることが多く、迷路探索や連結成分の判定などに使われる。"},{"id":55,"cat":"経営・戦略・法務","topic":"期待値の計算","q":"図の案Aは成功確率0.6で利益100万円、失敗確率0.4で損失20万円である。期待値はどれか。","choices":[{"label":"ア","text":"60万円"},{"label":"イ","text":"40万円"},{"label":"ウ","text":"52万円"},{"label":"エ","text":"68万円"}],"correct":"ウ","hint":"0.6×100+0.4×(−20)=60−8=52万円。損失は負の値として扱う点に注意。","image":"/images/diagrams/diagram2-q17.png"},{"id":56,"cat":"ネットワーク","topic":"スパニングツリープロトコル(STP)の目的","q":"冗長化のためにスイッチ間を複数経路で接続した場合に発生しうるループを検知し、一部のポートを論理的に閉塞してループを防止するプロトコルはどれか。","choices":[{"label":"ア","text":"OSPF(ルーティングプロトコル)"},{"label":"イ","text":"VRRP(ルータの冗長化プロトコル)"},{"label":"ウ","text":"LACP(リンク集約のプロトコル)"},{"label":"エ","text":"STP(スパニングツリープロトコル)"}],"correct":"エ","hint":"ブロードキャストストームを引き起こすループを防ぎつつ、冗長経路を障害時の予備として活用できる。"},{"id":57,"cat":"アルゴリズム・プログラミング","topic":"二分探索木の平衡が崩れた場合の問題","q":"二分探索木にデータを整列済みの順序でそのまま挿入し続けた場合に生じる問題として適切なものはどれか。","choices":[{"label":"ア","text":"挿入操作自体が実行時エラーになる"},{"label":"イ","text":"木が常に完全に平衡した形になり性能が向上する"},{"label":"ウ","text":"木が一直線状(片方に偏った形)になり、探索の計算量がO(log n)からO(n)に悪化する"},{"label":"エ","text":"メモリ使用量が半分になる"}],"correct":"ウ","hint":"整列済みデータをそのまま挿入すると木が線形リストのような形になり、二分探索木の利点(対数時間での探索)が失われる。"},{"id":58,"cat":"ネットワーク","topic":"サブネットのブロードキャストアドレス","q":"図の192.168.10.0/27に含まれるブロードキャストアドレスはどれか。","choices":[{"label":"ア","text":"192.168.10.32"},{"label":"イ","text":"192.168.10.27"},{"label":"ウ","text":"192.168.10.31"},{"label":"エ","text":"192.168.10.30"}],"correct":"ウ","hint":"/27はホスト部5ビットで32個区切り。0~31が1つの範囲であり、末尾の31がブロードキャストアドレスになる。","image":"/images/diagrams/diagram2-q9.png"},{"id":59,"cat":"ネットワーク","topic":"マルチキャストの用途","q":"特定のグループに参加している複数の受信者へ、1回の送信で同じデータを同時に届ける通信方式はどれか。","choices":[{"label":"ア","text":"ブロードキャスト(ネットワーク内の全端末への送信)"},{"label":"イ","text":"マルチキャスト"},{"label":"ウ","text":"ユニキャスト(1対1の通信)"},{"label":"エ","text":"エニーキャスト(グループ内の最も近い1台へ届ける方式)"}],"correct":"イ","hint":"映像配信やルーティングプロトコルの経路情報交換など、同じデータを複数の受信者へ効率よく届けたい場面で使われる。"},{"id":60,"cat":"コンピュータシステム","topic":"レジスタと主記憶のアクセス速度比較","q":"CPU内のレジスタと主記憶(メインメモリ)のデータアクセス速度を比較した場合の一般的な特徴はどれか。","choices":[{"label":"ア","text":"主記憶の方がレジスタよりも高速である"},{"label":"イ","text":"レジスタは主記憶よりもはるかに高速にアクセスできるが、容量は非常に小さい"},{"label":"ウ","text":"レジスタと主記憶のアクセス速度に違いはない"},{"label":"エ","text":"レジスタは主記憶よりも大容量である"}],"correct":"イ","hint":"レジスタはCPU内部に直接組み込まれているため極めて高速だが、その分容量は数個~数十個程度と非常に限られている。"},{"id":61,"cat":"基礎理論","topic":"論理回路(AND/NOT/NOR)","q":"図の論理回路で、A=1、B=0、C=1のとき、出力Xはどれか。","choices":[{"label":"ア","text":"0"},{"label":"イ","text":"Aと同じ"},{"label":"ウ","text":"1"},{"label":"エ","text":"Bと同じ"}],"correct":"ウ","hint":"上段はA AND B=0、下段はNOT C=0。最後にNOR(否定論理和)へ入れるため、NOT(0 OR 0)=1となる。","image":"/images/diagrams/diagram-q1.png"},{"id":62,"cat":"アルゴリズム・プログラミング","topic":"二分探索の計算量の理解","q":"要素数nの整列済み配列に対する二分探索の最悪計算量がO(log n)になる理由として適切なものはどれか。","choices":[{"label":"ア","text":"1回の比較のたびに探索範囲がほぼ半分に絞られ、範囲が1になるまでの比較回数がlog nに比例するため"},{"label":"イ","text":"比較のたびに探索範囲が1つずつ減るため(線形探索の説明)"},{"label":"ウ","text":"要素数に関わらず常に1回の比較で完了するため"},{"label":"エ","text":"1回の比較で必ず答えが見つかるため"}],"correct":"ア","hint":"n個の範囲をk回の比較でn/2^kまで絞り込めるため、n/2^k=1となるkがlog nのオーダーになる。"},{"id":63,"cat":"経営・戦略・法務","topic":"マズローの欲求段階説","q":"人間の欲求を生理的欲求から自己実現欲求まで階層的に整理した理論はどれか。","choices":[{"label":"ア","text":"ハーズバーグの動機付け・衛生理論(満足要因と不満足要因を分ける理論)"},{"label":"イ","text":"マズローの欲求段階説"},{"label":"ウ","text":"SWOT分析"},{"label":"エ","text":"PPM"}],"correct":"イ","hint":"低次の欲求(生理的欲求・安全欲求等)が満たされると、より高次の欲求(社会的欲求・承認欲求・自己実現欲求)が動機付けの中心になるという理論。"},{"id":64,"cat":"ネットワーク","topic":"SYN Flood攻撃の識別","q":"TCPの3ウェイハンドシェイクにおいて、大量のSYNパケットを送りつけながらACKを返さないことで、サーバの接続待ちリソースを枯渇させる攻撃はどれか。","choices":[{"label":"ア","text":"SYN Flood攻撃"},{"label":"イ","text":"フィッシング"},{"label":"ウ","text":"DNSキャッシュポイズニング"},{"label":"エ","text":"ARPスプーフィング(MACアドレス偽装による攻撃)"}],"correct":"ア","hint":"サーバは応答待ち(SYN_RECEIVED状態)の接続を大量に抱えることになり、正規の接続要求を処理できなくなる。"},{"id":65,"cat":"データベース","topic":"第3正規形への分割","q":"図の表で「社員ID→部署ID」「部署ID→部署名」が成り立つ。第3正規形にする分割として適切なものはどれか。","choices":[{"label":"ア","text":"社員(社員ID,部署ID)と部署(部署ID,部署名)"},{"label":"イ","text":"社員IDと部署名を削除"},{"label":"ウ","text":"社員(社員ID,部署名)だけ"},{"label":"エ","text":"部署(社員ID,部署ID,部署名)"}],"correct":"ア","hint":"社員IDから部署名への推移的関数従属を除くため、社員表(社員ID,部署ID)と部署表(部署ID,部署名)に分割する。","image":"/images/diagrams/diagram2-q12.png"},{"id":66,"cat":"アルゴリズム・プログラミング","topic":"状態遷移図のトレース","q":"図の自動販売機は待機状態から100円投入で受付状態へ移る。受付状態で取消を押したときの遷移として適切なものはどれか。","choices":[{"label":"ア","text":"停止へ移る"},{"label":"イ","text":"商品提供へ移る"},{"label":"ウ","text":"待機へ戻り100円を返す"},{"label":"エ","text":"受付のまま"}],"correct":"ウ","hint":"取消は取引を取り消し、投入金を返却して初期の待機状態へ戻る遷移になる。","image":"/images/diagrams/diagram2-q6.png"},{"id":67,"cat":"サービスマネジメント・監査","topic":"差分バックアップからの復元に必要な媒体","q":"図の運用で日曜にフルバックアップ、月~土曜に差分バックアップを取る。木曜終了時点を復元するのに必要な媒体はどれか。","choices":[{"label":"ア","text":"日曜フル+木曜差分"},{"label":"イ","text":"日曜フル+月~木曜の全差分"},{"label":"ウ","text":"日曜フルだけ"},{"label":"エ","text":"木曜差分だけ"}],"correct":"ア","hint":"差分バックアップは直前のフル以降の変更を毎回まとめて記録する。日曜のフルと木曜の差分の2つがあれば復元できる。","image":"/images/diagrams/diagram2-q20.png"},{"id":68,"cat":"サービスマネジメント・監査","topic":"キャパシティ管理の目的","q":"将来のシステム利用状況の変化を予測し、必要な処理能力やリソースを事前に確保・調整しておく活動を何と呼ぶか。","choices":[{"label":"ア","text":"変更管理(システムへの変更を制御する活動)"},{"label":"イ","text":"インシデント管理(発生した障害への対応活動)"},{"label":"ウ","text":"構成管理(IT資産の情報を管理する活動)"},{"label":"エ","text":"キャパシティ管理"}],"correct":"エ","hint":"需要の増加を見込んでリソースを計画的に増強することで、性能不足による障害やサービス品質の低下を未然に防ぐ。"},{"id":69,"cat":"アルゴリズム・プログラミング","topic":"キューのenqueue/dequeue操作","q":"空のキューに図の順で操作したとき(enqueue 10, enqueue 20, enqueue 30, dequeue, dequeue, dequeue)、最後のdequeueで取り出される値はどれか。","choices":[{"label":"ア","text":"30"},{"label":"イ","text":"空なのでエラー"},{"label":"ウ","text":"20"},{"label":"エ","text":"10"}],"correct":"ア","hint":"enqueue 10,20,30の順に入り、dequeueでは10、20、30の順に出る(FIFO)。3回目のdequeueで30が取り出される。","image":"/images/diagrams/diagram2-q4.png"},{"id":70,"cat":"アルゴリズム・プログラミング","topic":"UMLクラス図の継承関係","q":"図で「犬」から「動物」へ白抜き三角形の矢印が向いている。この関係はどれか。","choices":[{"label":"ア","text":"依存"},{"label":"イ","text":"継承(is-a)"},{"label":"ウ","text":"多重度"},{"label":"エ","text":"集約(has-a)"}],"correct":"イ","hint":"犬は動物の一種なのでis-a関係。UMLでは子クラスから親クラスへ白抜き三角形の矢印を向けて継承を表す。","image":"/images/diagrams/diagram2-q14.png"},{"id":71,"cat":"ネットワーク","topic":"tracerouteの仕組み(TTL)","q":"tracerouteコマンドが、送信元から宛先までの経路上にある各ルータを順番に特定できる仕組みの説明として適切なものはどれか。","choices":[{"label":"ア","text":"MACアドレスを順に書き換えて送信する"},{"label":"イ","text":"パケットのサイズを徐々に大きくして送信する"},{"label":"ウ","text":"TTL(生存時間)を1から順に増やしたパケットを送り、TTL超過で応答するルータを1台ずつ特定する"},{"label":"エ","text":"宛先ポート番号を1から順に変えて送信する"}],"correct":"ウ","hint":"TTLが0になったルータはパケットを破棄し、送信元へエラー通知を返すため、この応答から経路上の各ルータを順に特定できる。"},{"id":72,"cat":"アルゴリズム・プログラミング","topic":"安定なソートと不安定なソートの実務上の違い","q":"複数のキーで段階的にソートする(例えば部署ごとにグループ化した上で氏名順に並べる)場面で、安定なソートアルゴリズムを使うことが重要とされる理由はどれか。","choices":[{"label":"ア","text":"安定性は最終的なソート結果の正しさに一切影響しないため"},{"label":"イ","text":"安定なソートはメモリを一切使わないため"},{"label":"ウ","text":"先に行ったソート結果の順序を、後続のソートが不必要に崩さずに済むため"},{"label":"エ","text":"安定なソートは常に不安定なソートより高速であるため"}],"correct":"ウ","hint":"安定なソートは同じキー値を持つ要素の元の相対順序を保つため、複数キーでの段階的なソートを正しく積み重ねられる。"},{"id":73,"cat":"コンピュータシステム","topic":"GPUとCPUの処理特性の違い","q":"画像処理や機械学習の行列演算などで、CPUよりもGPUが高い性能を発揮しやすいとされる理由はどれか。","choices":[{"label":"ア","text":"GPUは複雑な分岐処理を伴う逐次処理に特化しているため"},{"label":"イ","text":"GPUは多数の単純な演算コアを持ち、大量のデータに対して同じ処理を並列に実行することを得意とするため"},{"label":"ウ","text":"GPUはメモリを一切使用せずに演算できるため"},{"label":"エ","text":"GPUは常にCPUより高いクロック周波数で動作するため"}],"correct":"イ","hint":"CPUは少数の高性能なコアで複雑な逐次処理を得意とするのに対し、GPUは多数のコアによる単純な並列演算に強みを持つ。"},{"id":74,"cat":"コンピュータシステム","topic":"アムダールの法則による性能向上計算","q":"図の処理時間100秒のうち80秒を5倍に高速化した。残り20秒が変わらないとき、新しい全処理時間はどれか。","choices":[{"label":"ア","text":"20秒"},{"label":"イ","text":"16秒"},{"label":"ウ","text":"36秒"},{"label":"エ","text":"40秒"}],"correct":"ウ","hint":"高速化部分は80÷5=16秒。高速化できない20秒を加えて16+20=36秒になる。全体を単純に5で割ってはいけない。","image":"/images/diagrams/diagram2-q8.png"},{"id":75,"cat":"ソフトウェア・HI","topic":"ドナルド・ノーマンの可視性の原則","q":"利用者が製品やインタフェースを見ただけで、どのような操作が可能か、現在どのような状態にあるかを把握できるようにするデザイン原則はどれか。","choices":[{"label":"ア","text":"制約の原則(誤った操作ができないよう物理的・論理的に制限する原則)"},{"label":"イ","text":"可視性(視認性)の原則"},{"label":"ウ","text":"フィードバックの原則(操作結果を利用者に伝えるべきという原則)"},{"label":"エ","text":"一貫性の原則(同じ操作は同じ結果をもたらすべきという原則)"}],"correct":"イ","hint":"操作可能な要素が見た目からも明確にわかることで、利用者が試行錯誤せずに直感的に操作できるようになる。"},{"id":76,"cat":"アルゴリズム・プログラミング","topic":"二重ループの疑似コード追跡","q":"図の疑似コード(count←0、iを0から2まで、jをi+1から3まで、a[i]>a[j]ならcount+1)を配列a=[4,1,3,2]で実行したとき、表示されるcountはどれか。","choices":[{"label":"ア","text":"5"},{"label":"イ","text":"4"},{"label":"ウ","text":"3"},{"label":"エ","text":"2"}],"correct":"イ","hint":"a[i]>a[j]となる組は(4,1),(4,3),(4,2),(3,2)の4個であり、countは4になる。","image":"/images/diagrams/diagram-q15.png"},{"id":77,"cat":"アルゴリズム・プログラミング","topic":"計算量記法(Θ記法とO記法の違い)","q":"アルゴリズムの計算量を表すO記法(オーダー記法)とΘ記法(シータ記法)の違いの説明として適切なものはどれか。","choices":[{"label":"ア","text":"O記法は上限(最悪でもこれ以下)を表すのに対し、Θ記法は上限と下限が一致する厳密な評価を表す"},{"label":"イ","text":"O記法とΘ記法に違いはなく完全に同じ意味である"},{"label":"ウ","text":"O記法は下限のみを表す"},{"label":"エ","text":"Θ記法は最良の場合の計算量のみを表す"}],"correct":"ア","hint":"O記法は「これより悪くはならない」という上界を保証する記法であり、Θ記法はより厳密に上界と下界が一致する場合に用いられる。"},{"id":78,"cat":"データベース","topic":"B木インデックスの探索効率","q":"多くのRDBMSのインデックスに採用されているB木(またはB+木)構造が、大量データに対しても高速な検索を実現できる理由はどれか。","choices":[{"label":"ア","text":"データを毎回全件スキャンして探索するため"},{"label":"イ","text":"木構造を使わず配列だけで実装されているため"},{"label":"ウ","text":"データを常にメモリ上にのみ保持し、ディスクを一切使わないため"},{"label":"エ","text":"木の高さが低く抑えられるよう設計されており、ディスクアクセス回数を少なく抑えて目的のデータへたどり着けるため"}],"correct":"エ","hint":"各ノードが複数のキーを持てる多分木構造により木の高さを低く抑えられ、ディスクI/Oの回数を大幅に削減できる。"},{"id":79,"cat":"基礎理論","topic":"有限状態機械による信号機の制御モデル","q":"信号機が「赤→青→黄→赤」と一定の順序で状態を繰り返す制御を、状態と遷移条件の組合せとしてモデル化する手法はどれか。","choices":[{"label":"ア","text":"有限状態機械(状態遷移図・状態遷移表)"},{"label":"イ","text":"ハッシュ法"},{"label":"ウ","text":"線形計画法(最適化問題を解く数理的手法)"},{"label":"エ","text":"動的計画法"}],"correct":"ア","hint":"「現在の状態」と「一定時間の経過」等の条件によって次の状態が一意に決まる制御の記述に、有限状態機械のモデルが適している。"},{"id":80,"cat":"基礎理論","topic":"固定小数点数と浮動小数点数の違い","q":"数値を表現する際、小数点の位置を固定して扱う方式と、指数部を用いて小数点の位置を動的に扱う方式の一般的な違いの説明として適切なものはどれか。","choices":[{"label":"ア","text":"両者に表現できる範囲の違いは一切ない"},{"label":"イ","text":"固定小数点数は表現できる範囲が限定的だが計算が単純、浮動小数点数は広い範囲を表現できるが誤差が生じやすい"},{"label":"ウ","text":"浮動小数点数には誤差が一切生じない"},{"label":"エ","text":"固定小数点数の方が常により広い範囲の数値を表現できる"}],"correct":"イ","hint":"浮動小数点数は指数部により非常に大きい値・小さい値まで表現できる一方、仮数部の桁数に応じた丸め誤差が生じやすい。"},{"id":81,"cat":"アルゴリズム・プログラミング","topic":"二分探索木の中順走査","q":"図の二分探索木を「左部分木→根→右部分木」の順(中順)で走査した結果はどれか。","choices":[{"label":"ア","text":"2,4,6,8,10,12,14"},{"label":"イ","text":"2,6,4,10,14,12,8"},{"label":"ウ","text":"8,4,2,6,12,10,14"},{"label":"エ","text":"8,12,14,10,4,6,2"}],"correct":"ア","hint":"中順走査は左側を処理してから根、最後に右側へ進む。二分探索木ではこの結果が必ず昇順になる。","image":"/images/diagrams/diagram-q12.png"},{"id":82,"cat":"アルゴリズム・プログラミング","topic":"ヒープソートの特徴","q":"配列をヒープ構造(親が子より大きい/小さいという性質を持つ完全二分木)に構成してから、根の要素を順に取り出していくソートアルゴリズムはどれか。","choices":[{"label":"ア","text":"バケットソート"},{"label":"イ","text":"バブルソート"},{"label":"ウ","text":"ヒープソート"},{"label":"エ","text":"挿入ソート"}],"correct":"ウ","hint":"ヒープソートは追加のメモリをほとんど必要とせず(インプレース)、最悪計算量でもO(n log n)を保証できる点が特徴。"},{"id":83,"cat":"データベース","topic":"トランザクションのACID特性","q":"データベースのトランザクションが満たすべき性質のうち、「処理の途中結果が他のトランザクションから見えない」ことを保証する性質はどれか。","choices":[{"label":"ア","text":"持続性(Durability、コミット後の結果が失われない性質)"},{"label":"イ","text":"原子性(Atomicity、処理が全て実行されるか全く実行されないかを保証する性質)"},{"label":"ウ","text":"独立性(Isolation)"},{"label":"エ","text":"一貫性(Consistency、データの整合性制約を保つ性質)"}],"correct":"ウ","hint":"独立性が保たれないと、あるトランザクションの未確定な変更を他のトランザクションが読み取ってしまう等の問題が生じる。"},{"id":84,"cat":"ネットワーク","topic":"伝送時間の計算(新数値)","q":"伝送速度150Mbpsの回線で45MBのファイルをアップロードするのにかかる理論上の最短時間に最も近いものはどれか(1バイト=8ビット、オーバーヘッドは無視する)。","choices":[{"label":"ア","text":"24秒"},{"label":"イ","text":"2.4秒"},{"label":"ウ","text":"0.3秒"},{"label":"エ","text":"3.0秒"}],"correct":"イ","hint":"45MB=360Mbitであり、150Mbpsの回線では360÷150=2.4秒で転送できる計算になる。"},{"id":85,"cat":"アルゴリズム・プログラミング","topic":"連結リストの逆順操作","q":"単方向連結リストの各ノードが持つ「次のノードへのポインタ」を、先頭から順にたどりながら逆向きに付け替えることでリスト全体を逆順にする操作の説明として適切なものはどれか。","choices":[{"label":"ア","text":"何もせず自動的に逆順として扱われる"},{"label":"イ","text":"各ノードを訪問するたびに、そのノードの次ポインタを1つ前のノードへ向け直していく"},{"label":"ウ","text":"リストの先頭と末尾のデータの値を1回だけ交換する"},{"label":"エ","text":"各ノードのデータの値だけを配列にコピーして並べ替える"}],"correct":"イ","hint":"ポインタの向きを1つずつ付け替えていくことで、追加のメモリをほとんど使わずにO(n)でリストを逆順にできる。"},{"id":86,"cat":"ソフトウェア・HI","topic":"フィッツの法則","q":"画面上のボタン等の対象物までの移動時間が、対象までの距離が長いほど長くなり、対象のサイズが大きいほど短くなるという関係を示した法則はどれか。","choices":[{"label":"ア","text":"パレートの法則(全体の大部分が一部の要素によって生み出されるという経験則)"},{"label":"イ","text":"フィッツの法則"},{"label":"ウ","text":"ミラーの法則(短期記憶で保持できる情報量に関する法則)"},{"label":"エ","text":"ヒックの法則(選択肢の数と意思決定時間の関係を示す法則)"}],"correct":"イ","hint":"画面の四隅や端は、事実上サイズが無限大とみなせるため、重要な操作ボタンを配置すると押しやすくなるとされる。"},{"id":87,"cat":"システム開発","topic":"モックとスタブの違い","q":"単体テストで使われる代役オブジェクトのうち、「呼び出されたかどうかや呼び出され方を検証する」ことに重点を置くものと、「あらかじめ決めた戻り値を返すだけ」のものの組合せはどれか。","choices":[{"label":"ア","text":"モック — スタブ"},{"label":"イ","text":"スタブ — モック(順序が逆)"},{"label":"ウ","text":"両方とも同じ役割で呼び方が違うだけである"},{"label":"エ","text":"モックとスタブに機能上の違いはない"}],"correct":"ア","hint":"スタブは単に固定の戻り値を返す代役、モックはさらに呼び出し回数や引数などの振る舞いを検証する機能を持つ代役として区別されることが多い。"},{"id":88,"cat":"経営・戦略・法務","topic":"損益分岐点販売数量の計算","q":"固定費300万円、製品1個の販売価格5万円、変動費3万円のとき、図の損益分岐点販売数量はどれか。","choices":[{"label":"ア","text":"300個"},{"label":"イ","text":"60個"},{"label":"ウ","text":"100個"},{"label":"エ","text":"150個"}],"correct":"エ","hint":"1個当たり限界利益は5−3=2万円。固定費300万円÷2万円=150個が損益分岐点の販売数量になる。","image":"/images/diagrams/diagram2-q18.png"},{"id":89,"cat":"基礎理論","topic":"真理値表の完成(AND/OR/NOT)","q":"図の真理値表の「?」に入る値の組合せはどれか。回路は (A OR B) AND (NOT A) である。","choices":[{"label":"ア","text":"上から0、0、0、0"},{"label":"イ","text":"上から1、0、1、0"},{"label":"ウ","text":"上から0、1、0、0"},{"label":"エ","text":"上から0、0、1、1"}],"correct":"ウ","hint":"A=0かつB=1の行だけ、(A OR B)=1かつNOT A=1が両立し、AND結果が1になる。","image":"/images/diagrams/diagram-q2.png"},{"id":90,"cat":"アルゴリズム・プログラミング","topic":"無向グラフの隣接行列","q":"図の無向グラフを隣接行列で表すとき、行B・列Dの要素はどれか。辺があれば1、なければ0とする。","choices":[{"label":"ア","text":"1"},{"label":"イ","text":"0"},{"label":"ウ","text":"2"},{"label":"エ","text":"頂点数による"}],"correct":"ア","hint":"図ではBとDが辺で直接結ばれているため1。無向グラフなので行D・列Bも同じく1になる(対称行列)。","image":"/images/diagrams/diagram-q17.png"},{"id":91,"cat":"アルゴリズム・プログラミング","topic":"スタックのpush/pop操作","q":"空のスタックに図の順で操作した(push 10, push 20, push 30, pop, pop, pop)。最後のpopで取り出される値はどれか。","choices":[{"label":"ア","text":"空なのでエラー"},{"label":"イ","text":"10"},{"label":"ウ","text":"30"},{"label":"エ","text":"20"}],"correct":"イ","hint":"push 10→20→30の後、最初のpopで30、次のpopで20、最後のpopで10が取り出される(LIFO)。","image":"/images/diagrams/diagram-q13.png"},{"id":92,"cat":"プロジェクトマネジメント","topic":"スコープクリープの概念","q":"プロジェクトの進行中に、正式な変更管理手続きを経ないまま、要求や作業範囲がなし崩し的に増えていく現象を何と呼ぶか。","choices":[{"label":"ア","text":"スコープクリープ"},{"label":"イ","text":"フロート(作業の余裕日数)"},{"label":"ウ","text":"マイルストーン(節目となる特定時点)"},{"label":"エ","text":"クリティカルパス(最長所要日数の経路)"}],"correct":"ア","hint":"適切な変更管理プロセスを経ずに範囲が膨張すると、当初の予算・スケジュールとの乖離が生じやすくなる。"},{"id":93,"cat":"基礎理論","topic":"ハフマン符号化の基本的な考え方","q":"出現頻度の高い文字には短い符号を、出現頻度の低い文字には長い符号を割り当てることで、全体のデータ量を圧縮する符号化方式はどれか。","choices":[{"label":"ア","text":"BCD符号化(10進数の各桁を2進数で表現する方式)"},{"label":"イ","text":"グレイコード(隣接する値のビット差が1になる符号化方式)"},{"label":"ウ","text":"ASCII符号化(全ての文字を固定長で表現する方式)"},{"label":"エ","text":"ハフマン符号化"}],"correct":"エ","hint":"頻度に応じて符号長を可変にすることで、固定長符号よりも全体のデータ量を小さくできる可逆圧縮の代表的な手法。"},{"id":94,"cat":"コンピュータシステム","topic":"RAID方式の識別","q":"図のようにデータとパリティを複数ディスクへ分散して記録し、1台の故障に耐えられる方式はどれか。","choices":[{"label":"ア","text":"RAID 5"},{"label":"イ","text":"RAID 1"},{"label":"ウ","text":"RAID 0"},{"label":"エ","text":"RAID 10"}],"correct":"ア","hint":"ブロック単位のストライピングに分散パリティを組み合わせるのがRAID 5。RAID 0には冗長性がなく1台の故障にも耐えられない。","image":"/images/diagrams/diagram2-q7.png"},{"id":95,"cat":"データベース","topic":"INNER JOINの結果行数","q":"図の社員表と部署表を部署IDでINNER JOINしたとき、結果の行数は何行か。","choices":[{"label":"ア","text":"4行"},{"label":"イ","text":"2行"},{"label":"ウ","text":"5行"},{"label":"エ","text":"3行"}],"correct":"エ","hint":"社員表のうち部署IDが部署表に存在するのはA(10)、B(20)、C(10)の3行。部署ID30のDは対応がなくINNER JOINでは除外される。","image":"/images/diagrams/diagram-q11.png"},{"id":96,"cat":"ネットワーク","topic":"サブネットの統合(スーパーネット化)","q":"192.168.4.0/24と192.168.5.0/24の2つのネットワークを、1つの経路情報にまとめる(スーパーネット化する)場合の最小のプレフィックス長はどれか。","choices":[{"label":"ア","text":"/22"},{"label":"イ","text":"/25"},{"label":"ウ","text":"/24"},{"label":"エ","text":"/23"}],"correct":"エ","hint":"2つの/24(256個×2=512個)をまとめるには、ホスト部が1ビット増えた/23(512個区切り)が必要になる。"},{"id":97,"cat":"アルゴリズム・プログラミング","topic":"貪欲法とバックトラック法の違い","q":"各段階で複数の選択肢を試し、行き詰まった場合には一つ前の状態に戻って別の選択肢を試す探索手法はどれか。","choices":[{"label":"ア","text":"貪欲法(一度選んだ選択を後で見直さない)"},{"label":"イ","text":"ヒープソート"},{"label":"ウ","text":"バックトラック法"},{"label":"エ","text":"二分探索法"}],"correct":"ウ","hint":"バックトラック法は候補を網羅的に探索するため計算コストは大きくなりがちだが、貪欲法では見つけられない厳密な最適解を得られる。"},{"id":98,"cat":"経営・戦略・法務","topic":"特許権と著作権の違い","q":"発明を保護する特許権と、プログラムの著作物を保護する著作権の権利発生に関する一般的な違いはどれか。","choices":[{"label":"ア","text":"両方とも創作した時点で自動的に発生する"},{"label":"イ","text":"特許権は特許庁への出願・審査・登録によって発生するが、著作権は創作した時点で自動的に発生する"},{"label":"ウ","text":"両方とも登録しなければ一切権利が発生しない"},{"label":"エ","text":"特許権の方が著作権より権利の存続期間が常に長い"}],"correct":"イ","hint":"著作権は無方式主義(登録不要)で創作と同時に発生するのに対し、特許権は出願・審査を経た登録によって初めて権利が発生する。"},{"id":99,"cat":"データベース","topic":"デッドロックの判定(待ちグラフ)","q":"図の待ちグラフでT1がT2を待ち、T2がT1を待っている。この状態はどれか。","choices":[{"label":"ア","text":"ロールフォワード"},{"label":"イ","text":"コミット"},{"label":"ウ","text":"デッドロック"},{"label":"エ","text":"排他制御"}],"correct":"ウ","hint":"待ち関係に循環があるため、互いに相手の解放を待ち続けるデッドロックの状態である。","image":"/images/diagrams/diagram2-q13.png"},{"id":100,"cat":"コンピュータシステム","topic":"コンピュータの起動処理(BIOS/UEFI)の役割","q":"コンピュータの電源投入直後に動作し、ハードウェアの初期化を行った後、OSを補助記憶装置から読み込んで起動を引き継ぐソフトウェアはどれか。","choices":[{"label":"ア","text":"BIOS/UEFI(ファームウェア)"},{"label":"イ","text":"ハイパーバイザー"},{"label":"ウ","text":"デバイスドライバ(OS上で個別機器を制御するソフト)"},{"label":"エ","text":"ミドルウェア"}],"correct":"ア","hint":"電源投入時に最初に動作し、ハードウェアの動作確認とOSの起動(ブートストラップ)を担う基本的なソフトウェアである。"}];

const C = {
  bg:"#0d1117", surface:"#161b22", surface2:"#1c2330", border:"#30363d",
  accent:"#58a6ff", green:"#3fb950", red:"#f85149", warn:"#d29922",
  text:"#e6edf3", muted:"#8b949e",
};

const s = {
  app:{ background:C.bg, minHeight:"100vh", padding:"20px 14px", fontFamily:"'Noto Sans JP',sans-serif", color:C.text },
  container:{ maxWidth:600, margin:"0 auto" },
  header:{ textAlign:"center", marginBottom:28 },
  h1:{ fontFamily:"monospace", fontSize:13, color:C.accent, letterSpacing:".1em", textTransform:"uppercase", marginBottom:4 },
  sub:{ color:C.muted, fontSize:12 },
  card:{ background:C.surface, border:`1px solid ${C.border}`, borderRadius:12, padding:20, marginBottom:14 },
  row:{ display:"flex", gap:8, flexWrap:"wrap", marginBottom:16 },
  chip:(a)=>({ padding:"5px 12px", background:a?"rgba(88,166,255,.1)":C.surface, border:`1px solid ${a?C.accent:C.border}`, borderRadius:20, color:a?C.accent:C.muted, fontSize:12, cursor:"pointer", fontFamily:"inherit" }),
  btn:(color=C.accent, outline=false)=>({ padding:"10px 20px", background:outline?"none":color, border:`1px solid ${color}`, borderRadius:8, color:outline?color:"#0d1117", fontFamily:"inherit", fontWeight:700, fontSize:14, cursor:"pointer" }),
  choiceBtn:(state)=>({
    width:"100%", padding:"11px 14px",
    background:state==="correct"?"rgba(63,185,80,.1)":state==="wrong"?"rgba(248,81,73,.1)":C.surface2,
    border:`1px solid ${state==="correct"?C.green:state==="wrong"?C.red:C.border}`,
    borderRadius:8, color:state==="correct"?C.green:state==="wrong"?C.red:C.text,
    fontFamily:"inherit", fontSize:16, textAlign:"left", cursor:state?"default":"pointer",
    display:"flex", gap:10, alignItems:"flex-start", lineHeight:1.5, marginBottom:7,
  }),
  label:{ fontFamily:"monospace", fontSize:14, color:C.muted, flexShrink:0, paddingTop:1 },
  fb:(ok)=>({ marginTop:14, padding:"12px 14px", borderRadius:8, fontSize:15, lineHeight:1.7, background:ok?"rgba(63,185,80,.08)":"rgba(248,81,73,.08)", border:`1px solid ${ok?"rgba(63,185,80,.3)":"rgba(248,81,73,.3)"}`, color:ok?C.green:C.red }),
  hintBox:{ marginTop:10, padding:"10px 12px", background:"rgba(255,255,255,.03)", border:`1px solid ${C.border}`, borderRadius:6, fontSize:14, color:C.muted, lineHeight:1.6 },
  hintLabel:{ fontSize:11, fontFamily:"monospace", color:C.accent, textTransform:"uppercase", letterSpacing:".05em", marginBottom:3 },
  progress:{ height:3, background:C.border, borderRadius:2, marginBottom:16, overflow:"hidden" },
  bar:(pct)=>({ height:"100%", background:C.accent, borderRadius:2, width:`${pct}%`, transition:"width .3s" }),
  meta:{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:12 },
  catTag:{ fontSize:11, padding:"2px 7px", background:"rgba(88,166,255,.1)", color:C.accent, borderRadius:4, fontFamily:"monospace" },
  qnum:{ fontSize:13, color:C.muted, fontFamily:"monospace", marginBottom:6 },
  qtext:{ fontSize:17, fontWeight:500, lineHeight:1.65, marginBottom:18 },
  tabs:{ display:"flex", gap:4, marginBottom:20, background:C.surface, padding:4, borderRadius:8, border:`1px solid ${C.border}` },
  tabBtn:(a)=>({ flex:1, padding:8, background:a?C.surface2:"none", border:"none", color:a?C.text:C.muted, fontFamily:"inherit", fontSize:15, borderRadius:6, cursor:"pointer", fontWeight:a?700:400 }),
  reviewItem:{ background:C.surface, border:`1px solid ${C.border}`, borderLeft:`3px solid ${C.red}`, borderRadius:8, padding:14, marginBottom:10 },
  sectionTitle:{ fontSize:11, color:C.muted, fontFamily:"monospace", textTransform:"uppercase", letterSpacing:".06em", margin:"20px 0 8px" },
  catBarRow:{ display:"flex", alignItems:"center", gap:8, marginBottom:8, background:C.surface, border:`1px solid ${C.border}`, borderRadius:8, padding:"9px 11px" },
  statBox:{ background:C.surface, border:`1px solid ${C.border}`, borderRadius:10, padding:"12px 8px", textAlign:"center", flex:1 },
  statNum:{ fontFamily:"monospace", fontSize:22, fontWeight:600, color:C.accent },
  statLabel:{ fontSize:11, color:C.muted, marginTop:2 },
  analysisBox:{ background:C.surface2, border:`1px solid ${C.border}`, borderRadius:10, padding:16, fontSize:13, lineHeight:1.8, color:C.text, whiteSpace:"pre-wrap" },
  spinner:{ display:"inline-block", width:16, height:16, border:`2px solid ${C.border}`, borderTop:`2px solid ${C.accent}`, borderRadius:"50%", animation:"spin 0.8s linear infinite", verticalAlign:"middle" },
  errBox:{ padding:"12px 14px", background:"rgba(248,81,73,.08)", border:`1px solid rgba(248,81,73,.3)`, borderRadius:8, color:C.red, fontSize:13, marginTop:12 },
  copyBox:{ background:C.surface2, border:`1px solid ${C.border}`, borderRadius:8, padding:12, fontSize:12, fontFamily:"monospace", color:C.muted, lineHeight:1.7, whiteSpace:"pre-wrap", wordBreak:"break-all", marginTop:8, maxHeight:160, overflowY:"auto" },
  copyBtn:(copied)=>({ padding:"8px 16px", background:copied?"rgba(63,185,80,.15)":"none", border:`1px solid ${copied?C.green:C.border}`, borderRadius:6, color:copied?C.green:C.muted, fontFamily:"inherit", fontSize:12, cursor:"pointer", transition:"all .2s" }),
  stockBadge:(n)=>({ display:"inline-block", padding:"2px 8px", borderRadius:10, fontSize:12, fontFamily:"monospace", fontWeight:700, background:n>=20?"rgba(63,185,80,.15)":n>0?"rgba(210,153,34,.15)":"rgba(248,81,73,.15)", color:n>=20?C.green:n>0?C.warn:C.red }),
};

function rateColor(p){ return p>=80?C.green:p>=50?C.warn:C.red; }
function shuffle(arr){ const a=[...arr]; for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];} return a; }

async function callClaude(messages, system){
  const apiKey = process.env.REACT_APP_ANTHROPIC_KEY || "";
  const headers = {"Content-Type":"application/json"};
  if(apiKey) headers["x-api-key"] = apiKey;
  const res = await fetch("https://api.anthropic.com/v1/messages",{
    method:"POST", headers,
    body:JSON.stringify({ model:"claude-sonnet-4-6", max_tokens:1000, system, messages }),
  });
  const data = await res.json();
  return data.content?.map(b=>b.text||"").join("")||"";
}

async function analyzeResults(questions, answers, catStats){
  const log = questions.map((q,i)=>`Q${i+1}[${q.cat}/${q.topic}]: ${answers[i]===q.correct?"○":"✗"}`).join("\n");
  const stats = Object.entries(catStats).map(([c,s])=>`${c}: ${Math.round(s.ok/s.total*100)}% (${s.ok}/${s.total}問)`).join("\n");
  const system = `あなたは基本情報技術者試験の学習コーチです。結果を分析し①弱点②強み・弱みの評価③次の学習ステップを250〜350字で返してください。`;
  return await callClaude([{role:"user",content:`【回答】\n${log}\n\n【累計】\n${stats}`}], system);
}

function ReviewCopyBox({ missedList, lifetimeByCat }){
  const [copied, setCopied] = useState(false);

  const buildText = useCallback(()=>{
    const now = new Date();
    const ds = `${now.getFullYear()}/${now.getMonth()+1}/${now.getDate()} ${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}`;
    const catGroup = {};
    missedList.forEach(q=>{ if(!catGroup[q.cat]) catGroup[q.cat]=[]; catGroup[q.cat].push(q); });
    const lines = [
      `📝 FE科目A 復習リスト ${ds}`,
      `間違えた問題: ${missedList.length}問`,
      `---`,
    ];
    Object.entries(catGroup).forEach(([cat, qs])=>{
      // 分野別の正解率は「累計(生涯)」の実績を使う。今回の周回だけの一時的な
      // 集計だと、ページを開き直した直後は0%になってしまうため。
      const st = lifetimeByCat[cat];
      const pct = st && st.total>0 ? Math.round(st.ok/st.total*100) : null;
      const pctLabel = pct===null ? "累計データなし" : `累計正解率 ${pct}%`;
      lines.push(`\n■ ${cat}（${pctLabel}）`);
      qs.forEach((q,i)=>{
        const cc = q.choices.find(c=>c.label===q.correct);
        lines.push(`Q: ${q.q}`);
        lines.push(`A: ${q.correct}. ${cc?.text}`);
        lines.push(`解説: ${q.hint}`);
        if(i < qs.length-1) lines.push("");
      });
    });
    return lines.join("\n");
  },[missedList, lifetimeByCat]);

  const handleCopy = useCallback(()=>{
    const text = buildText();
    navigator.clipboard.writeText(text).then(()=>{
      setCopied(true); setTimeout(()=>setCopied(false), 2000);
    }).catch(()=>{
      const ta = document.getElementById("review-copy-area");
      if(ta){ ta.value=text; ta.select(); document.execCommand("copy"); setCopied(true); setTimeout(()=>setCopied(false),2000); }
    });
  },[buildText]);

  return(
    <div style={{background:C.surface2, border:`1px solid ${C.border}`, borderRadius:10, padding:14, marginBottom:16}}>
      <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8}}>
        <div style={{fontSize:12, color:C.muted}}>📋 復習リストをチャットに貼る</div>
        <button style={s.copyBtn(copied)} onClick={handleCopy}>
          {copied ? "✓ コピーしました" : "コピー"}
        </button>
      </div>
      <div style={{fontSize:11, color:C.muted, lineHeight:1.6}}>
        間違えた問題の正解・解説を分野別にまとめたテキストをコピーできます。<br/>
        コピー後このチャットに貼り付けると履歴として残ります。
      </div>
      <textarea id="review-copy-area" readOnly value={buildText()}
        style={{position:"absolute", left:"-9999px", top:0}}/>
    </div>
  );
}

export default function App(){
  const [tab, setTab] = useState("quiz");
  const [cat, setCat] = useState("すべて");
  const [weakMode, setWeakMode] = useState(false);
  const [weakIds, setWeakIds] = useState([]);
  const [phase, setPhase] = useState("idle");
  const [usedIds, setUsedIds] = useState([]);
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState([]);
  const [qIdx, setQIdx] = useState(0);
  const [chosen, setChosen] = useState(null);
  const [showFb, setShowFb] = useState(false);
  const [analysis, setAnalysis] = useState("");
  const [allHistory, setAllHistory] = useState([]);
  const [savedSessions, setSavedSessions] = useState([]);
  const [lifetime, setLifetime] = useState({totalAnswered:0,totalCorrect:0,byCat:{}});
  const [missedList, setMissedList] = useState([]);
  const [catStats, setCatStats] = useState({});
  const [isWeakSession, setIsWeakSession] = useState(false);
  const [copyText, setCopyText] = useState("");
  const [copied, setCopied] = useState(false);
  const [progressLoading, setProgressLoading] = useState(true);
  const [progressError, setProgressError] = useState("");

  // 起動時にlocalStorageから進捗・履歴を復元
  useEffect(()=>{
    // 問題内容が(id構成として)前回と変わっていないかを確認する。
    // 変わっていた場合、古い周回進捗・復習リストは今の問題内容と対応しなくなるため
    // 自動的にクリアする(生涯累計・セッション履歴は問題内容が変わっても意味を持つため維持する)。
    const currentSignature = ALL_QUESTIONS.length + ":" + ALL_QUESTIONS.map(q=>q.id).join(",");
    let storedSignature = null;
    try{ storedSignature = localStorage.getItem(LS_QVERSION); }catch(e){}
    const contentChanged = storedSignature !== null && storedSignature !== currentSignature;
    if(contentChanged){
      try{
        localStorage.removeItem(LS_USED);
        localStorage.removeItem(LS_CYCLE);
        localStorage.removeItem(LS_MISSED);
      }catch(e){}
    }
    try{ localStorage.setItem(LS_QVERSION, currentSignature); }catch(e){}

    const ids = contentChanged ? [] : store.loadIds().filter(id => ALL_QUESTIONS.some(q=>q.id===id));
    if(ids.length > 0){
      setUsedIds(ids);
      setProgressError(`✓ 今の周回で${ids.length}問に解答済み（残り${ALL_QUESTIONS.length-ids.length}問／全${ALL_QUESTIONS.length}問）`);
    } else if(contentChanged){
      setProgressError(`問題の内容が更新されました。周回・復習リストを初期化しました（累計成績は引き続き保持されています）。`);
    }
    // 過去のセッション履歴を復元(直近最大100件、表示専用)
    const saved = store.loadSessions();
    if(saved.length > 0) setSavedSessions(saved);
    // 生涯累計を復元(こちらは間引かれない真の累計。問題内容が変わっても維持する)
    setLifetime(store.loadLifetime());
    // 復習リストを復元
    if(!contentChanged){
      const missed = store.loadMissed();
      if(missed.length > 0) setMissedList(missed);
    }
    // 今回の周回成績を復元(リロードしても消えない。usedIdsが空＝新しい周回なら
    // 古いcycleデータが残っていても無視して空から始める)
    if(ids.length > 0){
      const cyc = store.loadCycle();
      if(cyc.history && cyc.history.length > 0) setAllHistory(cyc.history);
      if(cyc.catStats) setCatStats(cyc.catStats);
    } else {
      store.clearCycle();
    }
    setProgressLoading(false);
  },[]); // eslint-disable-line

  // 残り問題数
  const available = ALL_QUESTIONS.filter(q=>{
    const catOk = cat==="すべて" || q.cat===cat;
    const notUsed = !usedIds.includes(q.id);
    return catOk && notUsed;
  });

  const saveUsedIds = useCallback((ids)=>{
    setUsedIds(ids);
    store.saveIds(ids);
  },[]);

  const startSession = useCallback(async()=>{
    let picked = [];
    const usingWeak = weakMode && weakIds.length > 0;
    setIsWeakSession(usingWeak);

    if(usingWeak){
      // 苦手優先：間違えた問題IDから優先出題
      const weakInAll = ALL_QUESTIONS.filter(q => weakIds.includes(q.id));
      const others = ALL_QUESTIONS.filter(q => !weakIds.includes(q.id) && (cat==="すべて" || q.cat===cat));
      const shuffledWeak = shuffle(weakInAll).slice(0, Math.min(10, weakInAll.length));
      const rest = shuffle(others).slice(0, Math.max(0, 10 - shuffledWeak.length));
      picked = shuffle([...shuffledWeak, ...rest]).slice(0, 10);
    } else {
      const base = ALL_QUESTIONS.filter(q=>(cat==="すべて"||q.cat===cat) && !usedIds.includes(q.id));
      if(base.length === 0){
        const fresh = ALL_QUESTIONS.filter(q=>cat==="すべて"||q.cat===cat);
        picked = shuffle(fresh).slice(0,10);
        saveUsedIds(picked.map(q=>q.id));
        // 全問題を1周し終えて新しい周回に入るため、今回の周回成績もリセットする
        setAllHistory([]); setCatStats({}); store.clearCycle();
      } else {
        // 残りが10問未満(周回の端数)の場合は、その残り分だけの少人数セッションにする。
        // 以前は残り10問未満で無条件に「周回終了」と誤判定し、周回の途中(例: 96問中90問時点)
        // でも今の周回の成績を強制リセットしてしまうバグがあった。
        const sessionSize = Math.min(10, base.length);
        picked = shuffle(base).slice(0, sessionSize);
        saveUsedIds([...usedIds, ...picked.map(q=>q.id)]);
      }
    }

    setQuestions(picked);
    setAnswers(new Array(picked.length).fill(null));
    setQIdx(0); setChosen(null); setShowFb(false);
    setAnalysis(""); setCopyText(""); setCopied(false);
    setPhase("question");
  },[cat, usedIds, weakMode, weakIds, saveUsedIds]);

  const handleAnswer = useCallback((choice)=>{
    if(showFb) return;
    setChosen(choice); setShowFb(true);
    const q = questions[qIdx];
    const ok = choice.label===q.correct;
    // 苦手優先モードは既出問題を意図的に何度も再出題する復習用モードのため、
    // 「今の周回(1周=全問題を重複なく1回ずつ)」の集計(allHistory/catStats)には含めない。
    // 含めてしまうと同じ問題が何度もカウントされ、分野の合計がその分野の
    // 実際の問題数を超えるなど、集計が壊れる原因になっていた。
    if(!isWeakSession){
      setAllHistory(h=>{
        const updatedHistory=[...h,{cat:q.cat,topic:q.topic,correct:ok}];
        setCatStats(prev=>{
          const cur=prev[q.cat]||{ok:0,total:0};
          const updatedStats={...prev,[q.cat]:{ok:cur.ok+(ok?1:0),total:cur.total+1}};
          store.saveCycle({history:updatedHistory, catStats:updatedStats});
          return updatedStats;
        });
        return updatedHistory;
      });
    }
    if(!ok){
      setMissedList(m=>{
        const updated=[...m,q];
        store.saveMissed(updated);
        return updated;
      });
    }
    setAnswers(prev=>{const n=[...prev];n[qIdx]=choice.label;return n;});
  },[showFb,questions,qIdx,isWeakSession]);

  const handleNext = useCallback(()=>{
    const next=qIdx+1;
    if(next>=questions.length) setPhase("score");
    else{setQIdx(next);setChosen(null);setShowFb(false);}
  },[qIdx,questions.length]);

  const sessionCorrect = answers.filter((a,i)=>a!==null&&questions[i]&&a===questions[i].correct).length;


  useEffect(()=>{
    if(phase==="score"&&questions.length>0){
      if(copyText===""){
        const now=new Date();
        const ds=`${now.getFullYear()}/${now.getMonth()+1}/${now.getDate()} ${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}`;
        const correct=answers.filter((a,i)=>a!==null&&questions[i]&&a===questions[i].correct).length;
        const lines=[
          `📊 FE科目A クイズ結果 ${ds}`,
          `正解: ${correct}/${questions.length}問 (${Math.round(correct/questions.length*100)}%)`,
          `分野: ${[...new Set(questions.map(q=>q.cat))].join("・")}`,
          `---`,
          ...questions.map((q,i)=>`Q${i+1}[${q.cat}/${q.topic}] ${answers[i]===q.correct?"○":"✗"}`),
          `---`,
          `累計分野別:`,
          ...Object.entries(catStats).map(([c,s])=>`${c}: ${Math.round(s.ok/s.total*100)}% (${s.ok}/${s.total})`),
        ];
        setCopyText(lines.join("\n"));

        // このセッションの分野別集計を作りlocalStorageへ永続化する
        const sessionCats = {};
        questions.forEach((q,i)=>{
          if(!sessionCats[q.cat]) sessionCats[q.cat]={ok:0,total:0};
          sessionCats[q.cat].total+=1;
          if(answers[i]!==null && answers[i]===q.correct) sessionCats[q.cat].ok+=1;
        });
        const session={
          date: now.getTime(),
          cat: cat,
          total: questions.length,
          correct: correct,
          pct: Math.round(correct/questions.length*100),
          cats: sessionCats,
        };
        store.addSession(session);
        setSavedSessions(prev=>{
          const updated=[...prev, session];
          return updated.length>100 ? updated.slice(updated.length-100) : updated;
        });
        setLifetime(store.loadLifetime());
      }
    }
  },[phase]); // eslint-disable-line

  const loadDbHistory = useCallback(()=>{ /* localStorage版は履歴タブで直接表示 */ },[]);

  const clearDbMissed = useCallback(async()=>{
    if(!window.confirm("復習リストを全削除しますか？")) return;
    setDbMissed([]);
  },[]);

  const handleAnalyze = useCallback(async()=>{
    setPhase("analyzing");
    try{
      const result=await analyzeResults(questions,answers,catStats);
      setAnalysis(result);
      setCopyText(prev=>prev+"\n---\n📝 AI分析:\n"+result);
    }catch{setAnalysis("分析の取得に失敗しました。");}
    finally{setPhase("score");}
  },[questions,answers,catStats]);

  const resetSession = useCallback(()=>{setPhase("idle");setAnalysis("");setCopyText("");setCopied(false);},[]);
  const clearMissed = useCallback(()=>{ setMissedList([]); store.saveMissed([]); },[]);

  // 「今の周回」の集計はallHistory(今の周回で回答した{cat,correct}の記録)から
  // 毎回計算し直す。allHistoryはusedIdsと必ず同じタイミングでリセットされるため
  // (store.clearCycle()を常に一緒に呼んでいる)、この2つの間にズレは生じない。
  // ※missedList(復習リスト)は周回をまたいで蓄積し続ける別物であり、
  // 「今の周回」の集計には使えない(前回、誤って使ってしまい負の値になるバグを出した)。
  const cycleStats = (()=>{
    const byCat = {};
    allHistory.forEach(h=>{
      if(!byCat[h.cat]) byCat[h.cat] = { ok:0, total:0 };
      byCat[h.cat].total += 1;
      if(h.correct) byCat[h.cat].ok += 1;
    });
    const totalAnswered = allHistory.length;
    const totalCorrect = allHistory.filter(h=>h.correct).length;
    return { byCat, totalAnswered, totalCorrect };
  })();
  const totalAnswered = cycleStats.totalAnswered;
  const totalCorrect = cycleStats.totalCorrect;
  const overallPct=totalAnswered>0?Math.round(totalCorrect/totalAnswered*100):0;

  return(
    <div style={s.app}>
      <style>{`@keyframes spin{to{transform:rotate(360deg)}} @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&display=swap');`}</style>
      <div style={s.container}>
        <header style={s.header}>
          <div style={s.h1}>FE 科目A Quiz</div>
          <div style={s.sub}>基本情報技術者 — 100問内蔵(図表40+対策60)</div>
          <a href="/b" style={{display:"inline-block",marginTop:8,fontSize:12,color:C.accent,textDecoration:"none",border:`1px solid ${C.accent}`,borderRadius:6,padding:"4px 10px"}}>科目Bの問題を解く →</a>
        </header>

        <div style={s.tabs}>
          {["quiz","review","history"].map((t,i)=>(
            <button key={t} style={s.tabBtn(tab===t)} onClick={()=>{ setTab(t); if(t==="history") loadDbHistory(); }}>
              {["クイズ",`復習${missedList.length>0?` (${missedList.length})`:""}`, "履歴・分析"][i]}
            </button>
          ))}
        </div>

        {tab==="quiz" && <>
          {phase==="idle" && (
            <div style={s.card}>
              {progressLoading ? (
                <div style={{textAlign:"center",padding:20,color:C.muted,fontSize:13}}>
                  <span style={s.spinner}/> <span style={{marginLeft:8}}>進捗を読み込み中…</span>
                </div>
              ) : (
                <div style={{marginBottom:12,fontSize:13,color:C.muted}}>
                  残り問題: <span style={s.stockBadge(available.length)}>{available.length}問</span>
                  <span style={{fontSize:11,color:C.muted,marginLeft:8}}>/ {ALL_QUESTIONS.length}問中</span>
                  {progressError && <div style={{fontSize:11,color:progressError.startsWith("✓")?C.green:C.warn,marginTop:4}}>{progressError}</div>}
                </div>
              )}
              <div style={{marginBottom:16}}>
                <div style={{fontSize:11,color:C.muted,fontFamily:"monospace",marginBottom:8,textTransform:"uppercase",letterSpacing:".06em"}}>分野</div>
                <div style={s.row}>
                  {CATS.map(c=><button key={c} style={s.chip(cat===c)} onClick={()=>setCat(c)}>{c}</button>)}
                </div>
              </div>
              <button style={{...s.btn(),width:"100%"}} onClick={startSession}>
                {weakMode ? "🎯 苦手優先モードでスタート" : `スタート（${Math.min(10, available.length===0?10:available.length)}問）`}
              </button>
              {/* 苦手優先モード切替 */}
              <div style={{display:"flex",alignItems:"center",gap:10,marginTop:10,padding:"10px 12px",background:weakMode?"rgba(63,185,80,.08)":"rgba(255,255,255,.03)",border:`1px solid ${weakMode?C.green:C.border}`,borderRadius:8,cursor:"pointer"}}
                onClick={async()=>{
                  const next = !weakMode;
                  setWeakMode(next);
                  if(next){
                    // localStorageの復習リストから苦手IDを取得
                    const ids = missedList.map(q=>q.id);
                    setWeakIds([...new Set(ids)]);
                  }
                }}>
                <div style={{width:36,height:20,background:weakMode?C.green:C.border,borderRadius:10,position:"relative",flexShrink:0,transition:"background .2s"}}>
                  <div style={{width:16,height:16,background:"white",borderRadius:"50%",position:"absolute",top:2,left:weakMode?18:2,transition:"left .2s"}}/>
                </div>
                <div>
                  <div style={{fontSize:13,color:weakMode?C.green:C.muted,fontWeight:weakMode?700:400}}>苦手優先モード</div>
                  <div style={{fontSize:11,color:C.muted}}>{weakMode && weakIds.length>0 ? `${weakIds.length}問を優先出題` : "復習リストの問題を優先"}</div>
                </div>
              </div>
              <button style={{width:"100%",padding:9,background:"none",border:`1px solid ${C.border}`,color:C.muted,borderRadius:8,fontFamily:"inherit",fontSize:12,cursor:"pointer",marginTop:8}}
                onClick={()=>{ if(window.confirm("使用済み問題をリセットして全問を出題可能にします。今回の周回成績もリセットされます。よろしいですか？")){ saveUsedIds([]); setAllHistory([]); setCatStats({}); store.clearCycle(); } }}>
                🔄 問題をリセット（全100問に戻す）
              </button>
              <button style={{width:"100%",padding:9,background:"none",border:`1px solid #7f1d1d`,color:"#f87171",borderRadius:8,fontFamily:"inherit",fontSize:12,cursor:"pointer",marginTop:8}}
                onClick={()=>{
                  if(!window.confirm("累計成績・履歴・復習リストを含む全てのデータを完全に削除します。これまでの学習記録は元に戻せません。本当によろしいですか？")) return;
                  if(!window.confirm("最終確認です。累計解答数・正解率など、これまでの記録は全て消えます。本当に実行しますか？")) return;
                  try{
                    localStorage.removeItem(LS_USED);
                    localStorage.removeItem(LS_SESSIONS);
                    localStorage.removeItem(LS_MISSED);
                    localStorage.removeItem(LS_LIFETIME);
                    localStorage.removeItem(LS_CYCLE);
                    localStorage.removeItem(LS_QVERSION);
                  }catch(e){}
                  window.location.reload();
                }}>
                🗑️ 完全リセット（累計成績も含めて全データ削除）
              </button>
            </div>
          )}

          {phase==="question" && questions[qIdx] && (()=>{
            const q=questions[qIdx];
            return(
              <div>
                <div style={s.progress}><div style={s.bar((qIdx/questions.length)*100)}/></div>
                <div style={s.card}>
                  <div style={s.meta}>
                    <span style={{fontFamily:"monospace",fontSize:12,color:C.muted}}>{qIdx+1} / {questions.length}</span>
                    <span style={s.catTag}>{q.cat}</span>
                  </div>
                  <div style={s.qnum}>テーマ: {q.topic}</div>
                  <div style={s.qtext}>{q.q}</div>
                  {q.image && (
                    <div style={{margin:"10px 0 16px",textAlign:"center"}}>
                      <img src={q.image} alt="図表" style={{maxWidth:"100%",borderRadius:8,border:`1px solid ${C.border}`}} />
                    </div>
                  )}
                  <div>
                    {q.choices.map(c=>{
                      let state=null;
                      if(showFb){if(c.label===q.correct)state="correct";else if(chosen?.label===c.label)state="wrong";}
                      return(
                        <button key={c.label} style={s.choiceBtn(state)} onClick={()=>handleAnswer(c)} disabled={showFb}>
                          <span style={s.label}>{c.label}</span><span>{c.text}</span>
                        </button>
                      );
                    })}
                  </div>
                  {showFb && (
                    <div>
                      <div style={s.fb(chosen?.label===q.correct)}>
                        {chosen?.label===q.correct?"✓ 正解！":`✗ 不正解。正解は ${q.correct}. ${q.choices.find(c=>c.label===q.correct)?.text}`}
                        <div style={s.hintBox}><div style={s.hintLabel}>解説</div>{q.hint}</div>
                        {chosen?.label!==q.correct && (
                          <div style={{...s.hintBox,marginTop:8,borderColor:"rgba(248,81,73,.2)"}}>
                            <div style={{...s.hintLabel,color:C.warn}}>あなたの選択</div>
                            {chosen?.label}. {chosen?.text}
                          </div>
                        )}
                      </div>
                      <button style={{...s.btn(),width:"100%",marginTop:14}} onClick={handleNext}>
                        {qIdx+1>=questions.length?"結果を見る":"次の問題 →"}
                      </button>
                    </div>
                  )}
                </div>
              </div>
            );
          })()}

          {(phase==="score"||phase==="analyzing") && (
            <div style={{...s.card,textAlign:"center"}}>
              <div style={{fontFamily:"monospace",fontSize:48,fontWeight:600,color:C.accent,marginBottom:4}}>
                {sessionCorrect} / {questions.length}
              </div>
              <div style={{color:C.muted,fontSize:13,marginBottom:20}}>
                正解率 {Math.round(sessionCorrect/questions.length*100)}%
                {Math.round(sessionCorrect/questions.length*100)>=80?" — 完璧に近い！":Math.round(sessionCorrect/questions.length*100)>=60?" — 惜しい、復習しよう":" — 復習タブで確認を"}
              </div>
              <div style={{textAlign:"left",marginBottom:20}}>
                {questions.map((q,i)=>{
                  const ok=answers[i]===q.correct;
                  return(
                    <div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",padding:"7px 0",borderBottom:`1px solid ${C.border}`,gap:8}}>
                      <div style={{fontSize:12}}>
                        <span style={{fontFamily:"monospace",color:C.muted,marginRight:6}}>Q{i+1}</span>
                        <span style={{color:C.muted,fontSize:11}}>[{q.cat}]</span>
                        <span style={{marginLeft:6}}>{q.topic}</span>
                      </div>
                      <span style={{fontFamily:"monospace",color:ok?C.green:C.red,flexShrink:0}}>{ok?"○":"✗"}</span>
                    </div>
                  );
                })}
              </div>
              <div style={{display:"flex",gap:8,justifyContent:"center",flexWrap:"wrap",marginBottom:16}}>
                <button style={s.btn()} onClick={startSession}>もう一度</button>
                <button style={s.btn(C.accent,true)} onClick={resetSession}>設定に戻る</button>
              </div>
              <div style={{textAlign:"left"}}>
                <div style={s.sectionTitle}>AI 学習分析</div>
                {analysis?(
                  <div style={s.analysisBox}>{analysis}</div>
                ):(
                  <button style={{...s.btn(C.green),width:"100%"}} onClick={handleAnalyze} disabled={phase==="analyzing"}>
                    {phase==="analyzing"?<><span style={s.spinner}/><span style={{marginLeft:8}}>分析中…</span></>:"このセッションをAIに分析してもらう"}
                  </button>
                )}
              </div>
              {copyText && (
                <div style={{textAlign:"left",marginTop:20}}>
                  <div style={s.sectionTitle}>📋 チャットに貼り付ける用</div>
                  <div style={{display:"flex",justifyContent:"flex-end",marginBottom:4}}>
                    <button style={s.copyBtn(copied)} onClick={()=>{
                      navigator.clipboard.writeText(copyText).then(()=>{setCopied(true);setTimeout(()=>setCopied(false),2000);})
                      .catch(()=>{const el=document.getElementById("copyarea");if(el){el.select();document.execCommand("copy");setCopied(true);setTimeout(()=>setCopied(false),2000);}});
                    }}>{copied?"✓ コピーしました":"コピー"}</button>
                  </div>
                  <textarea id="copyarea" readOnly value={copyText}
                    style={{...s.copyBox,width:"100%",resize:"none",outline:"none"}} rows={8}/>
                  <div style={{fontSize:11,color:C.muted,marginTop:4}}>コピーしてチャットに貼り付けると履歴として残ります</div>
                </div>
              )}
            </div>
          )}
        </>}

        {tab==="review" && (
          <div>
            {missedList.length===0
              ?<div style={{textAlign:"center",color:C.muted,fontSize:14,padding:"48px 0"}}>間違えた問題はまだありません。</div>
              :<>
                {/* コピーテキスト生成 */}
                <ReviewCopyBox missedList={missedList} lifetimeByCat={lifetime.byCat||{}}/>
                <button style={{width:"100%",padding:9,background:"none",border:`1px solid ${C.border}`,color:C.muted,borderRadius:8,fontFamily:"inherit",fontSize:13,cursor:"pointer",marginBottom:16}} onClick={clearMissed}>復習リストをクリア</button>
                {missedList.map((q,i)=>{
                  const cc=q.choices.find(c=>c.label===q.correct);
                  return(
                    <div key={i} style={s.reviewItem}>
                      <div style={{fontSize:11,color:C.muted,fontFamily:"monospace",marginBottom:4}}>{q.cat} / {q.topic}</div>
                      <div style={{fontSize:13,fontWeight:500,lineHeight:1.6,marginBottom:8}}>{q.q}</div>
                      {q.image && (
                        <div style={{margin:"6px 0 10px"}}>
                          <img src={q.image} alt="図表" style={{maxWidth:"100%",borderRadius:6,border:`1px solid ${C.border}`}} />
                        </div>
                      )}
                      <div style={s.hintLabel}>正解</div>
                      <div style={{fontSize:13,color:C.text,marginBottom:6,lineHeight:1.5}}>{q.correct}. {cc?.text}</div>
                      <div style={{fontSize:12,color:C.muted,lineHeight:1.6}}>{q.hint}</div>
                    </div>
                  );
                })}
              </>
            }
          </div>
        )}

        {tab==="history" && (
          <div>
            <div style={{display:"flex",gap:8,marginBottom:18}}>
              {[["解答数",totalAnswered],["正解数",totalCorrect],["正解率",`${overallPct}%`]].map(([l,v],i)=>(
                <div key={l} style={s.statBox}>
                  <div style={{...s.statNum,color:i===2?rateColor(overallPct):C.accent}}>{v}</div>
                  <div style={s.statLabel}>{l}（今の周回）</div>
                </div>
              ))}
            </div>
            {Object.keys(cycleStats.byCat).length>0 && <>
              <div style={s.sectionTitle}>分野別 正解率（今の周回・{ALL_QUESTIONS.length}問を1周する間ずっと蓄積）</div>
              {Object.entries(cycleStats.byCat)
                .map(([c,st])=>({c,pct:Math.round(st.ok/st.total*100),ok:st.ok,total:st.total}))
                .sort((a,b)=>a.pct-b.pct)
                .map(({c,pct,ok,total})=>(
                  <div key={c} style={s.catBarRow}>
                    <div style={{fontSize:12,width:140,flexShrink:0,lineHeight:1.3}}>{c}</div>
                    <div style={{flex:1,height:7,background:C.surface2,borderRadius:4,overflow:"hidden"}}>
                      <div style={{height:"100%",borderRadius:4,width:`${pct}%`,background:rateColor(pct),transition:"width .4s"}}/>
                    </div>
                    <div style={{fontFamily:"monospace",fontSize:12,width:72,textAlign:"right",color:rateColor(pct)}}>
                      {pct}% ({ok}/{total})
                    </div>
                  </div>
                ))
              }
            </>}

            {/* 累計成績(fe_lifetime基準、間引かれない真の累計)＋直近セッション一覧(表示専用) */}
            {(lifetime.totalAnswered > 0 || savedSessions.length > 0) && (()=>{
              const totalA = lifetime.totalAnswered;
              const totalC = lifetime.totalCorrect;
              const ovPct = totalA>0?Math.round(totalC/totalA*100):0;
              const aggCats = lifetime.byCat || {};
              return <>
                <div style={s.sectionTitle}>📦 累計（全セッション）</div>
                <div style={{display:"flex",gap:8,marginBottom:12}}>
                  {[["累計解答",totalA],["累計正解",totalC],["累計正解率",`${ovPct}%`]].map(([l,v],i)=>(
                    <div key={l} style={s.statBox}>
                      <div style={{...s.statNum,color:i===2?rateColor(ovPct):C.accent,fontSize:16}}>{v}</div>
                      <div style={s.statLabel}>{l}</div>
                    </div>
                  ))}
                </div>
                {Object.keys(aggCats).length>0 && <>
                  <div style={s.sectionTitle}>累計分野別正解率</div>
                  {Object.entries(aggCats)
                    .map(([c,st])=>({c,pct:Math.round(st.ok/st.total*100),ok:st.ok,total:st.total, legacy: !CATS.includes(c)}))
                    .sort((a,b)=>a.pct-b.pct)
                    .map(({c,pct,ok,total,legacy})=>(
                      <div key={c} style={s.catBarRow}>
                        <div style={{fontSize:12,width:140,flexShrink:0,lineHeight:1.3,color:legacy?C.muted:undefined}}>{c}{legacy?"（分野再編前の記録）":""}</div>
                        <div style={{flex:1,height:7,background:C.surface2,borderRadius:4,overflow:"hidden"}}>
                          <div style={{height:"100%",borderRadius:4,width:`${pct}%`,background:rateColor(pct),transition:"width .4s"}}/>
                        </div>
                        <div style={{fontFamily:"monospace",fontSize:12,width:72,textAlign:"right",color:rateColor(pct)}}>{pct}% ({ok}/{total})</div>
                      </div>
                    ))
                  }
                </>}
                <div style={s.sectionTitle}>直近のセッション（最新20件）</div>
                <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"4px 13px",marginBottom:12}}>
                  {savedSessions.slice(-20).reverse().map((sess,i)=>{
                    const d=new Date(sess.date);
                    const ds=`${d.getMonth()+1}/${d.getDate()} ${String(d.getHours()).padStart(2,"0")}:${String(d.getMinutes()).padStart(2,"0")}`;
                    return(
                      <div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"8px 0",borderBottom:i<Math.min(savedSessions.length,20)-1?`1px solid ${C.border}`:"none"}}>
                        <span style={{fontSize:12,color:C.muted,fontFamily:"monospace"}}>{ds} ・ {sess.cat}</span>
                        <span style={{fontFamily:"monospace",fontSize:13,fontWeight:600,color:rateColor(sess.pct)}}>{sess.correct}/{sess.total}</span>
                      </div>
                    );
                  })}
                </div>
                <button style={{width:"100%",padding:9,background:"none",border:`1px solid ${C.border}`,color:C.muted,borderRadius:8,fontFamily:"inherit",fontSize:12,cursor:"pointer"}}
                  onClick={()=>{ if(window.confirm("直近のセッション一覧のみ削除します(累計成績は消えません)。よろしいですか？")){ localStorage.removeItem("fe_sessions"); setSavedSessions([]); } }}>
                  直近セッション一覧をクリア
                </button>
              </>;
            })()}
            {totalAnswered===0 && savedSessions.length===0 && <div style={{textAlign:"center",color:C.muted,fontSize:13,padding:"12px 0"}}>クイズに挑戦すると履歴が表示されます。</div>}
          </div>
        )}
      </div>
    </div>
  );
}
